window.YUWEN_QUESTIONS = {"meta":{"subject":"山东专升本大学语文","groups":11,"per_group":"20+10+20","total":549,"unique":549,"rebuilt":"2026-10-29","types":["句子→篇目","释义→词条","作品→作者","实词辨析","句子翻译"],"note":"选择题由「篇目/名句/实词/常识」结构化字段按模板生成，经六道门禁校验（题干为疑问句、答案不在题干、干扰项同范畴、无拼接残留、选项长度均衡、选项唯一）；p3 翻译题保留原解析。","rebuild":"2026-10-31"},"groups":[{"no":1,"date":"2026-10-29","date_end":"2026-10-30","pieces":["季氏将伐颛臾","鸿门宴","传是楼记","勾践灭吴","子路曾皙冉有公西华侍坐","逍遥游"],"theme":"综合练习 1","p1":[{"q":"《谏逐客书》选自（　）","opts":["史记","昭明文选","嘉祐集","庄子"],"ans":"A","atext":"史记","src":"篇目→出处","note":"《谏逐客书》选自《史记·李斯列传》（亦见《文选》）。"},{"q":"何其芳生活于（　）","opts":["西汉","战国末期","秦代","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"何其芳，现代。"},{"q":"《吕相绝秦》的作者是（　）","opts":["孔子","左丘明","晁错","苏轼"],"ans":"B","atext":"左丘明","src":"篇目→作者","note":"《吕相绝秦》：春秋，左丘明，选自《左传·成公十三年》。"},{"q":"叶圣陶生活于（　）","opts":["现代","战国末期","秦代","战国"],"ans":"A","atext":"现代","src":"人物→朝代","note":"叶圣陶，现代。"},{"q":"麦家生活于（　）","opts":["秦代","西汉","当代","战国"],"ans":"C","atext":"当代","src":"人物→朝代","note":"麦家，当代。"},{"q":"铁凝生活于（　）","opts":["北魏","当代","战国","北宋"],"ans":"B","atext":"当代","src":"人物→朝代","note":"铁凝，当代。"},{"q":"郝景芳生活于（　）","opts":["西汉","战国末期","当代","北宋"],"ans":"C","atext":"当代","src":"人物→朝代","note":"郝景芳，当代。"},{"q":"施蛰存生活于（　）","opts":["北宋","北魏","现代","战国末期"],"ans":"C","atext":"现代","src":"人物→朝代","note":"施蛰存，现代。"},{"q":"司马光生活于（　）","opts":["北魏","春秋","北宋","战国末期"],"ans":"C","atext":"北宋","src":"人物→朝代","note":"司马光，北宋。"},{"q":"神话生活于（　）","opts":["春秋","先秦","秦代","战国末期"],"ans":"B","atext":"先秦","src":"人物→朝代","note":"神话，先秦。"},{"q":"《小翠》的作者是（　）","opts":["汪琬","韩愈","司马迁","蒲松龄"],"ans":"D","atext":"蒲松龄","src":"篇目→作者","note":"《小翠》：清，蒲松龄，选自《聊斋志异》卷七。"},{"q":"宋玉生活于（　）","opts":["北宋","战国末期","战国","春秋"],"ans":"C","atext":"战国","src":"人物→朝代","note":"宋玉，战国。"},{"q":"马原生活于（　）","opts":["秦代","北魏","战国末期","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"马原，当代。"},{"q":"屈原生活于（　）","opts":["西汉","北魏","北宋","战国"],"ans":"D","atext":"战国","src":"人物→朝代","note":"屈原，战国。"},{"q":"柳青生活于（　）","opts":["北魏","战国末期","北宋","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"柳青，当代。"},{"q":"孟子生活于（　）","opts":["春秋","战国","北宋","战国末期"],"ans":"B","atext":"战国","src":"人物→朝代","note":"孟子，战国。"},{"q":"墨子生活于（　）","opts":["秦代","战国","北魏","北宋"],"ans":"B","atext":"战国","src":"人物→朝代","note":"墨子，战国。"},{"q":"田汉生活于（　）","opts":["现代","北宋","战国","战国末期"],"ans":"A","atext":"现代","src":"人物→朝代","note":"田汉，现代。"},{"q":"典故生活于（　）","opts":["西汉","春秋","战国末期","北宋"],"ans":"D","atext":"北宋","src":"人物→朝代","note":"典故，北宋。"},{"q":"许地山生活于（　）","opts":["北宋","秦代","现代","战国末期"],"ans":"C","atext":"现代","src":"人物→朝代","note":"许地山，现代。"}],"p2":[{"q":"「盖亦反其本矣。」中「盖」的意思是（　）","opts":["恐怕，莫非（表推测）","快、迅速","通\"盍\"，何不。","黑色染料黑泥（音niè）"],"ans":"C","atext":"通\"盍\"，何不。","src":"实词释义","note":"《齐桓晋文之事》盖亦反其本矣。　盖(hé)：通\"盍\"，何不；反通\"返\"。"},{"q":"「踵门而告文公曰。」中「踵」的意思是（　）","opts":["脚后跟，引申为走到、亲自到。","通“熟”，仔细","违背、相反（迕wǔ）","名词作动词，游水、游泳"],"ans":"A","atext":"脚后跟，引申为走到、亲自到。","src":"实词释义","note":"《许行》踵门而告文公曰。　踵门：亲自登门。"},{"q":"「粟有所渫」中「渫」的意思是（　）","opts":["说，谈论。","错误、过失","疏散、流通（音xiè）","私下、谦指自己"],"ans":"C","atext":"疏散、流通（音xiè）","src":"实词释义","note":"《论贵粟疏》粟有所渫　指粮食有流通去处。"},{"q":"「唐氏之弃地，货而不售」中「货」的意思是（　）","opts":["出卖","宽恕","经过","甚、很"],"ans":"A","atext":"出卖","src":"实词释义","note":"《钴鉧潭西小丘记》唐氏之弃地，货而不售　货：卖；不售：卖不出去。"},{"q":"「稽其成败兴坏之纪」中「稽」的意思是（　）","opts":["鉴戒、教训","考订、探究","通“纳”，接纳","出使的人"],"ans":"B","atext":"考订、探究","src":"实词释义","note":"《报任安书》稽其成败兴坏之纪　稽：考核。"},{"q":"「自非亭午夜分，不见曦月」中「曦」的意思是（　）","opts":["日光，此指太阳","（水）枯竭，减少。","边邑，边境","节操、操守"],"ans":"A","atext":"日光，此指太阳","src":"实词释义","note":"《巫山巫峡》自非亭午夜分，不见曦月　“曦”本指清晨阳光，这里代指太阳。"},{"q":"「婴金铁受辱」中「婴」的意思是（　）","opts":["缠绕、被加在身","推却、拒绝","通“又”","突然、仓猝"],"ans":"A","atext":"缠绕、被加在身","src":"实词释义","note":"《报任安书》婴金铁受辱　婴：绕，指颈戴铁索。"},{"q":"「两涘渚崖之间，不辩牛马。」中「辩」的意思是（　）","opts":["通\"智\"，智慧。","在公众场合指责、议论（讥：谏）","通\"辨\"，分辨，辨别。","阻止、遏制"],"ans":"C","atext":"通\"辨\"，分辨，辨别。","src":"实词释义","note":"《秋水》两涘渚崖之间，不辩牛马。　辩(biàn)：分辨。"},{"q":"「下而从六国破亡之故事」中「故事」的意思是（　）","opts":["操劳，劳作。","旧事、前例","怨恨、抱怨","高险如屏障的山峰"],"ans":"B","atext":"旧事、前例","src":"实词释义","note":"《六国论》下而从六国破亡之故事　今义指叙事性文学体裁。"},{"q":"「天下之欲疾其君者，皆欲赴愬于王。」中「愬」的意思是（　）","opts":["用于主谓之间，取消句子独立性","通\"诉\"，申诉，控诉。","通\"凭\"，凭借、乘。","通“悦”，高兴"],"ans":"B","atext":"通\"诉\"，申诉，控诉。","src":"实词释义","note":"《齐桓晋文之事》天下之欲疾其君者，皆欲赴愬于王。　愬(sù)：通\"诉\"。"}],"p3":[{"q":"君子疾夫舍曰欲之而必为之辞。","a":"君子最痛恨那种嘴上不说想要，却一定要为它找个借口的做法。","note":"疾：痛恨；辞：托辞；揭穿冉有文过饰非。","src":"季氏将伐颛臾"},{"q":"大行不顾细谨，大礼不辞小让。","a":"做大事不必顾及细枝末节，行大礼不必计较小的责备。","note":"“让”责备；互文。樊哙劝刘邦离席不必告辞。","src":"鸿门宴"},{"q":"盖尝慨夫为人之父祖者，每欲传其土田货财，而子孙未必能世富也；","a":"我曾感慨那些做父祖辈的，常常想把土地钱财传给子孙，但子孙不一定能世代富足；","note":"世：名词作状语，世代。三组排比起兴。","src":"传是楼记"},{"q":"今健庵先生既出其所得于书者，上为天子之所器重，次为中朝士大夫之所矜式，藉是以润色大业，对扬休命，有余矣，而又推之以训敕其子姓，俾后先跻巍科，取宦仕，翕然有名于当世，琬然后喟焉太息，以为读书之益弘矣哉！循是道也，虽传诸子孙世世，何不可之有？","a":"如今健庵先生既已拿出他从书中所得的，上为天子所器重，次为朝廷士大夫所敬仰效法，借此来润色大业，应对称扬美好的任命，绰绰有余了，又推而用来训导他的子孙，使他们先后登上高科、取得官职，一起在当世有名声，我然后感叹，认为读书的益处大啊！遵循这个道理，即使传给子孙世世代代，又有什么不可以呢？","note":"矜式：敬重效法；润色：修饰增色；对扬休命：对答称扬美好的任命。跻：登上。循是道：遵循这个道理。","src":"传是楼记"},{"q":"令壮者无取老妇，令老者无取壮妻；女子十七不嫁，其父母有罪；丈夫二十不取，其父母有罪。","a":"令壮年男子不得娶老妇，老年男子不得娶壮妻；女子十七不嫁、男子二十不娶，父母都定罪。","note":"取通娶。奖励生育的法令。","src":"勾践灭吴"},{"q":"千乘之国，摄乎大国之间，加之以师旅，因之以饥馑。","a":"一个拥有千辆兵车的国家，夹在大国之间，外有军队侵犯，内又接上饥荒。","note":"“加之以师旅”“因之以饥馑”均为状语后置，即“以师旅加之”“以饥馑因之”。","src":"子路曾皙冉有公西华侍坐"},{"q":"虎兕出于柙，龟玉毁于椟中，是谁之过与？","a":"猛虎犀牛从笼子里跑出来，龟甲美玉在匣子里毁坏，这是谁的过错呢？","note":"两处“于”字结构均状语后置；比喻季氏失责、冉有季路难辞其咎。","src":"季氏将伐颛臾"},{"q":"我决起而飞，抢榆枋而止，时则不至，而控于地而已矣。","a":"我迅速起飞，碰上榆树枋树就停下，有时飞不到，落在地上罢了。","note":"决起：疾起；抢：触、撞；控：落下。写蜩与学鸠的短见，与鹏对比。","src":"逍遥游"},{"q":"守一城，捍天下，以千百就尽之卒，战百万日滋之师，蔽遮江淮，沮遏其势，天下之不亡，其谁之功也！","a":"守住一座孤城，捍卫整个天下，率领千百名将要死尽的士兵，迎战百万日益增多的叛军，掩护了江淮大地，阻止了叛军攻势，天下之所以没有灭亡，那是谁的功劳呢！","note":"就尽：将死尽；日：名词作状语，一天天；其谁之功：反问语气。全句对偶排比，盛赞张巡许远之功。","src":"张中丞传后叙"},{"q":"此五子者，不产于秦，而穆公用之，并国二十，遂霸西戎。","a":"这五位贤士，都不出生在秦国，可是穆公重用他们，吞并了二十国，于是称霸西戎。","note":"“产”出生；“霸”名词作动词，称霸。举例论证四君用客之功。","src":"谏逐客书"},{"q":"至丹以荆卿为计，始速祸焉。","a":"等到燕太子丹用派荆轲刺杀秦王作为对策，才招致了祸患。","note":"速：招致（非迅速）。点出燕亡的直接原因。","src":"六国论"},{"q":"夫腹饥不得食，肤寒不得衣，虽慈母不能保其子，君安能以有其民哉！","a":"肚子饥饿没有吃的，皮肤寒冷没有衣穿，即使是慈爱的母亲也不能保全她的孩子，国君又怎么能拥有他的百姓呢！","note":"反问句加强语气；“安能”怎么能。推论明君必须务民农桑。","src":"论贵粟疏"},{"q":"故夫知效一官，行比一乡，德合一君，而征一国者，其自视也，亦若此矣。而宋荣子犹然笑之。且举世誉之而不加劝，举世非之而不加沮，定乎内外之分，辩乎荣辱之境，斯已矣。彼其于世，未数数然也。虽然，犹有未树也。","a":"所以那些才智足以胜任一个官职、品行能够联合一乡之人、德行能够使一国之君满意、能力能够取信于一国之人的人，他们看待自己，也像斥鴳这样罢了。而宋荣子还讥笑他们。而且全社会都称赞他，他也不会因此更加努力；全社会都非议他，他也不会因此更加沮丧。他认定了内我和外物的分际，辨明了光荣和耻辱的界限，这就罢了。他对于世俗的名誉，没有急切追求。虽然如此，他还是没有树立至高的境界。","note":"知：通「智」，才智；效：胜任；比：合于、联合；而征一国：而通「能」，能力；数数然：急切追求的样子；未树：未树立至高境界。","src":"逍遥游"},{"q":"夫子喟然叹曰：“吾与点也！”","a":"孔子长叹一声说：“我赞同曾点的想法啊！”","note":"与（yù）：赞同；喟然：长叹的样子。","src":"子路曾皙冉有公西华侍坐"},{"q":"段不弟，故不言弟；如二君，故曰克。","a":"共叔段不守弟道，所以《春秋》不称弟；像两个国君交战，所以用“克”。","note":"点明《春秋》书法。弟：名词作动词，尽弟道。","src":"郑伯克段于鄢"},{"q":"凡为橱者七十有二，部居类汇，各以其次，素标缃帙，启钥灿然。","a":"一共做了七十二个书橱，按经史子集分类排列，各按次序，白色的标签、浅黄色的书套，打开锁后灿烂夺目。","note":"有通“又”；素标缃帙：形容藏书精良。写藏书之富。","src":"传是楼记"},{"q":"秋水时至，百川灌河。泾流之大，两涘渚崖之间，不辩牛马。于是焉河伯欣然自喜，以天下之美为尽在己。顺流而东行，至于北海，东面而视，不见水端。于是焉河伯始旋其面目，望洋向若而叹曰：\"野语有之曰：'闻道百，以为莫己若者。'我之谓也。且夫我尝闻少仲尼之闻而轻伯夷之义者，始吾弗信。今我睹子之难穷也，吾非至于子之门则殆矣，吾长见笑于大方之家。\"","a":"秋天的洪水按季节到来，许多河流的水注入黄河。水流的浩大，两岸和沙洲之间，连牛马都分辨不清。于是河伯欣然自喜，认为天下的美景全在自己这里。顺着水流向东行，到了北海，向东望去，看不到水的尽头。于是河伯才改变了他自得的面貌，望着大海对北海若感叹说：\"俗话有这样一种说法：'听了一百种道理，就以为没有人比得上自己。'说的就是我啊。而且我曾经听说有人小看孔子的见闻、轻视伯夷的道义，起初我不相信；如今我看到你这样难以穷尽，我如果不是来到你的门前就危险了，我将永远被有修养的人耻笑。\"","note":"时：名词作状语，按季节；泾流：水流；辩：通「辨」，分辨；望洋：仰视的样子；大方之家：有修养的人。被动句「见笑于」。","src":"秋水"},{"q":"是从我糠覈不得饱，一旦置身广厦，役婢仆，厌膏粱，彼意适，我愿慰矣，岂卖菜也而索直乎！","a":"这姑娘跟着我粗劣饭都吃不饱，一旦住进高楼大厦，使唤婢仆，饱食美味，她称心如意，我的心愿也满足了，难道是卖菜的还要讨价还价吗！","note":"厌通“餍”；直通“值”。写虞氏不要聘金，反常可疑。","src":"小翠"},{"q":"向使四君却客而不内，疏士而不用，是使国无富利之实，而秦无强大之名也。","a":"假使四位君主拒绝客卿而不予接纳，疏远贤士而不加任用，这就会使国家没有丰厚的实力，秦国也没有强大的名声了。","note":"“向使”假使；“内”通“纳”。反面假设论证（虚拟语气）。","src":"谏逐客书"},{"q":"他人有心，予忖度之。──夫子之谓也。","a":"别人有什么心思，我能揣测到。──说的就是先生您啊。","note":"\"夫子之谓也\"：宾语前置（谓夫子也），\"之\"作标志。","src":"齐桓晋文之事"}]},{"no":2,"date":"2026-10-30","date_end":"2026-10-31","pieces":["齐桓晋文之事","留侯论","谏逐客书","季氏将伐颛臾","张中丞传后叙","传是楼记"],"theme":"综合练习 2","p1":[{"q":"老舍生活于（　）","opts":["战国末期","北宋","现代","战国"],"ans":"C","atext":"现代","src":"人物→朝代","note":"老舍，现代。"},{"q":"《子路曾皙冉有公西华侍坐》的作者是（　）","opts":["司马迁","孔子","刘向","左丘明"],"ans":"B","atext":"孔子","src":"篇目→作者","note":"《子路曾皙冉有公西华侍坐》：春秋，孔子，选自《论语·先进》。"},{"q":"《报任安书》的作者是（　）","opts":["司马迁","晁错","蒲松龄","郦道元"],"ans":"A","atext":"司马迁","src":"篇目→作者","note":"《报任安书》：西汉，司马迁，选自《昭明文选》卷四十一（亦见《汉书·司马迁传》）。"},{"q":"钱锺书生活于（　）","opts":["秦代","战国","现代","战国末期"],"ans":"C","atext":"现代","src":"人物→朝代","note":"钱锺书，现代。"},{"q":"曾朴生活于（　）","opts":["战国","秦代","战国末期","清末"],"ans":"D","atext":"清末","src":"人物→朝代","note":"曾朴，清末。"},{"q":"王安忆生活于（　）","opts":["战国末期","当代","秦代","西汉"],"ans":"B","atext":"当代","src":"人物→朝代","note":"王安忆，当代。"},{"q":"孙犁生活于（　）","opts":["秦代","西汉","战国末期","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"孙犁，当代。"},{"q":"范成大生活于（　）","opts":["南宋","战国","战国末期","西汉"],"ans":"A","atext":"南宋","src":"人物→朝代","note":"范成大，南宋。"},{"q":"陈忠实生活于（　）","opts":["当代","北宋","北魏","西汉"],"ans":"A","atext":"当代","src":"人物→朝代","note":"陈忠实，当代。"},{"q":"诸葛亮生活于（　）","opts":["三国蜀","春秋","北魏","秦代"],"ans":"A","atext":"三国蜀","src":"人物→朝代","note":"诸葛亮，三国蜀。"},{"q":"苏洵生活于（　）","opts":["北宋","秦代","战国末期","西汉"],"ans":"A","atext":"北宋","src":"人物→朝代","note":"苏洵，北宋。"},{"q":"席慕蓉生活于（　）","opts":["战国末期","北宋","战国","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"席慕蓉，当代。"},{"q":"钱钟书生活于（　）","opts":["西汉","当代","北宋","战国末期"],"ans":"B","atext":"当代","src":"人物→朝代","note":"钱钟书，当代。"},{"q":"杂文集生活于（　）","opts":["北魏","西汉","当代","战国"],"ans":"C","atext":"当代","src":"人物→朝代","note":"杂文集，当代。"},{"q":"郦道元生活于（　）","opts":["北宋","北魏","春秋","西汉"],"ans":"B","atext":"北魏","src":"人物→朝代","note":"郦道元，北魏。"},{"q":"周作人生活于（　）","opts":["战国末期","战国","现代","北宋"],"ans":"C","atext":"现代","src":"人物→朝代","note":"周作人，现代。"},{"q":"洪深生活于（　）","opts":["战国末期","战国","现代","西汉"],"ans":"C","atext":"现代","src":"人物→朝代","note":"洪深，现代。"},{"q":"《齐桓公伐楚》选自（　）","opts":["论语","尧峰文钞","左传","庄子"],"ans":"C","atext":"左传","src":"篇目→出处","note":"《齐桓公伐楚》选自《左传·僖公四年》。"},{"q":"赵树理生活于（　）","opts":["战国","西汉","北魏","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"赵树理，当代。"},{"q":"《齐桓晋文之事》选自（　）","opts":["战国策","孟子","聊斋志异","汉书"],"ans":"B","atext":"孟子","src":"篇目→出处","note":"《齐桓晋文之事》选自《孟子·梁惠王上》。"}],"p2":[{"q":"「虢叔死焉」中「焉」的意思是（　）","opts":["出使的人","于此，在那里","疲困、衰败","刚才，先前。"],"ans":"B","atext":"于此，在那里","src":"实词释义","note":"《郑伯克段于鄢》虢叔死焉　兼词，相当于“于是/于之”。"},{"q":"「公伐诸鄢」中「诸」的意思是（　）","opts":["阻止、遏制","夹、迫近","直流的水，河面水流。","“之于”的合音"],"ans":"D","atext":"“之于”的合音","src":"实词释义","note":"《郑伯克段于鄢》公伐诸鄢　诸=之于。"},{"q":"「深受而翁庇翼」中「而翁」的意思是（　）","opts":["预料，料想","命运、定数","并力，合力","你的父亲"],"ans":"D","atext":"你的父亲","src":"实词释义","note":"《小翠》深受而翁庇翼　而：通“尔”，你。"},{"q":"「王之蔽甚矣」中「蔽」的意思是（　）","opts":["计算、数着","战胜，攻克","受蒙蔽","遇合、际遇"],"ans":"C","atext":"受蒙蔽","src":"实词释义","note":"《邹忌讽齐王纳谏》王之蔽甚矣　被动意味：王被蒙蔽（受蒙蔽很深）。"},{"q":"「大臣强谏」中「强」的意思是（　）","opts":["轮流、交替","疏通，疏导。","竭力、极力","操劳，劳作。"],"ans":"C","atext":"竭力、极力","src":"实词释义","note":"《触龙说赵太后》大臣强谏　强（qiǎng）谏：极力劝谏。"},{"q":"「井蛙不可以语于海者，拘于虚也。」中「虚」的意思是（　）","opts":["通\"墟\"，所居之处，这里指井穴。","城郭坚固、兵力充实","通“煣”，用火烤木材使之弯曲","劝说、游说（音shuì）"],"ans":"A","atext":"通\"墟\"，所居之处，这里指井穴。","src":"实词释义","note":"《秋水》井蛙不可以语于海者，拘于虚也。　虚：通\"墟\"，井栏、所居之处。"},{"q":"「吾与女同好弃恶」中「女」的意思是（　）","opts":["通“俸”，俸禄","屯驻，退守","空闲。","通“汝”，你"],"ans":"D","atext":"通“汝”，你","src":"实词释义","note":"《吕相绝秦》吾与女同好弃恶　女读rǔ。"},{"q":"「焉辟害」中「辟」的意思是（　）","opts":["遭受、蒙受","通“避”，躲避","平时、平素家居","其、他们的"],"ans":"B","atext":"通“避”，躲避","src":"实词释义","note":"《郑伯克段于鄢》焉辟害　辟，躲避。"},{"q":"「吾何以传女曹哉」中「女曹」的意思是（　）","opts":["尽、全","你们","行走","雨过天晴"],"ans":"B","atext":"你们","src":"实词释义","note":"《传是楼记》吾何以传女曹哉　女（rǔ）通“汝”；曹：辈、们。"},{"q":"「或王命急宣」中「或」的意思是（　）","opts":["偏爱","或者","有时","世代"],"ans":"C","atext":"有时","src":"实词释义","note":"《巫山巫峡》或王命急宣　“或”在古汉语中常作无定代词“有时、有的人”。"}],"p3":[{"q":"臣未之闻也。","a":"我没有听说过这件事。","note":"宾语前置（未闻之），否定句代词\"之\"作宾语前置。","src":"齐桓晋文之事"},{"q":"匹夫见辱，拔剑而起，挺身而斗，此不足为勇也。","a":"普通人被侮辱，就拔起剑站起身，挺身上前搏斗，这算不上勇敢。","note":"见：表被动。以“匹夫之勇”反衬下文“大勇”。","src":"留侯论"},{"q":"王曰：\"否，吾何快于是，将以求吾所大欲也。\"","a":"宣王说：\"不，我怎么会对这些感到痛快，我是想借此求得我最想要的东西。\"","note":"快于是：状语后置，即「于是快」，对此感到痛快；大欲：最想得到的东西。","src":"齐桓晋文之事"},{"q":"无恒产而有恒心者，惟士为能；若民，则无恒产，因无恒心。","a":"没有固定产业而有恒定心志的，只有读书人能做到；至于百姓，没有固定产业，就没有恒定心志。","note":"恒产：固定产业。提出制民之产的仁政主张。","src":"齐桓晋文之事"},{"q":"昭王得范雎，废穰侯，逐华阳，强公室，杜私门，蚕食诸侯，使秦成帝业。","a":"昭王得到范雎，废黜穰侯，驱逐华阳君，加强王室权力，堵塞权贵私门，像蚕吃桑叶一样逐步侵占诸侯，使秦国成就帝王基业。","note":"“强”使动（使公室强）；“蚕食”名词作状语（像蚕一样）。四句四事，排比紧凑。","src":"谏逐客书"},{"q":"季氏将有事于颛臾。","a":"季孙氏将要对颛臾动兵。","note":"“于颛臾”状语后置；“有事”讳言用兵。","src":"季氏将伐颛臾"},{"q":"及其无救而且穷也，将其创残饿羸之余，虽欲去，必不达。","a":"等到没有救兵而且处境困窘的时候，率领着那些受伤饥饿残剩的士卒，即使想撤离，也必定到不了。","note":"穷：困厄；创残饿羸：受伤残弱、饥饿瘦弱；将（jiàng）：率领。","src":"张中丞传后叙"},{"q":"曰：\"有复于王者曰：吾力足以举百钧，而不足以举一羽；明足以察秋毫之末，而不见舆薪。则王许之乎？\"","a":"孟子说：\"如果有人向大王报告说：我的力气足以举起三千斤，却举不起一根羽毛；我的视力足以看清秋天鸟兽新生细毛的末梢，却看不见一车柴草。那么大王相信他吗？\"","note":"复：通「覆」，禀报；钧：三十斤；秋毫之末：鸟兽秋天新生细毛的末端，极言细小；舆薪：一车柴草；许：相信。","src":"齐桓晋文之事"},{"q":"不得已勉承先生之命，姑为一言复之，先生亦恕其老誖否耶？","a":"不得已勉强承受先生的嘱托，姑且说几句话回复您，先生能原谅我的老昏谬乱吧？","note":"老誖（bèi）：老昏悖乱。以谦辞作结。","src":"传是楼记"},{"q":"循是道也，虽传诸子孙世世，何不可之有？","a":"遵循这条道路，即使把它传给子子孙孙世世代代，又有什么不可以呢？","note":"何不可之有：宾语前置（有何不可）。赞徐氏传书之道。","src":"传是楼记"},{"q":"后稷教民稼穑，树艺五谷，五谷熟而民人育。","a":"后稷教百姓庄稼，种植五谷，五谷成熟了百姓才能养育繁衍。","note":"树、艺：种植。写后稷教农之功。","src":"许行"},{"q":"《齐谐》者，志怪者也。《谐》之言曰：\"鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。\"野马也，尘埃也，生物之以息相吹也。天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。","a":"《齐谐》这本书，是记载怪异之事的。《齐谐》上说：\"鹏迁往南海的时候，翅膀拍击水面激起三千里波涛，乘着旋风盘旋而上升到九万里高空，是凭借六月的大风而离去的。\"像野马奔腾的雾气，飞扬的尘埃，都是生物用气息相互吹拂的结果。天空苍苍茫茫，那是它真正的颜色吗？还是因为高远而看不到尽头呢？大鹏从高空往下看，也不过就像这样罢了。","note":"志：记；抟：盘旋；扶摇：旋风；野马：像野马奔腾的雾气；息：气息。判断句「……者，……也」。","src":"逍遥游"},{"q":"吾何以传女曹哉？吾徐先世，故以清白起家，吾耳目濡染旧矣。","a":"我拿什么东西传给你们呢？我们徐家先世，本来就以清白操守起家，我耳濡目染已经很久了。","note":"女（rǔ）通“汝”，你们。领起传家之问。","src":"传是楼记"},{"q":"观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。项籍唯不能忍，是以百战百胜而轻用其锋；高祖忍之，养其全锋而待其弊，此子房教之也。当淮阴破齐而欲自王，高祖发怒，见于词色。由此观之，犹有刚强不忍之气，非子房其谁全之？","a":"看汉高祖之所以胜利、项羽之所以失败的原因，就在能忍与不能忍之间罢了。项羽只因不能忍，所以百战百胜却轻易使用他的锋芒；汉高祖能忍耐，保全他的全部锋芒来等待项羽的疲敝，这是张良教他的。当淮阴侯攻破齐国想自立为王时，汉高祖发怒，表现在言辞脸色上。由此看来，他还有刚强不能忍的气质，如果不是张良，谁能保全他呢？","note":"所以：……的原因；锋：锋芒、锐气；弊：疲敝；全之：保全他。","src":"留侯论"},{"q":"贾人夏则资皮，冬则资絺，旱则资舟，水则资车，以待乏也。","a":"商人夏天就囤皮货，冬天就备细葛布，旱时备船，水时备车，用来等待缺乏时使用。","note":"排比设喻，说明平时要早作准备。","src":"勾践灭吴"},{"q":"于是入朝见威王，曰：“臣诚知不如徐公美。臣之妻私臣，臣之妾畏臣，臣之客欲有求于臣，皆以美于徐公。今齐地方千里，百二十城，宫妇左右莫不私王，朝廷之臣莫不畏王，四境之内莫不有求于王：由此观之，王之蔽甚矣。”","a":"于是邹忌上朝拜见齐威王，说：\"我确实知道自己不如徐公美。可是我的妻子偏爱我，我的妾害怕我，我的客人有求于我，他们都认为我比徐公美。如今齐国土地方圆千里，有一百二十座城池，宫中的妃子和身边的近臣没有不偏爱大王的，朝廷上的大臣没有不害怕大王的，全国范围内的人没有不对大王有所求的：由此看来，大王受到的蒙蔽太厉害了。\"","note":"诚：确实；私：偏爱；地方：古今异义，土地方圆；蔽：受蒙蔽。","src":"邹忌讽齐王纳谏"},{"q":"老者衣帛食肉，黎民不饥不寒：然而不王者，未之有也。","a":"老年人穿丝帛、吃肉食，百姓不挨饿受冻：这样还不能统一天下，是从来没有过的事。","note":"衣(yì)：名作动，穿；未之有：宾语前置（未有之）。全文以仁政蓝图作结。","src":"齐桓晋文之事"},{"q":"太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令，其次诎体受辱，其次易服受辱，其次关木索、被箠楚受辱，其次剔毛发、婴金铁受辱，其次毁肌肤、断肢体受辱，最下腐刑极矣。","a":"最上等的是不使祖先受辱，其次是不使自身受辱，其次是不在道理脸色上受辱，其次是不在言辞上受辱，其次是被捆绑受辱，其次是换上囚服受辱，其次是戴上木枷绳索、遭刑杖拷打受辱，其次是剃发戴铁圈受辱，其次是毁坏肌肤、截断肢体受辱，最下等的就是受腐刑，这达到屈辱的顶点了。","note":"“太上”最上等；“辱”均使动，使……受辱；“诎”通“屈”；“婴”缠绕（颈戴铁索）。十层排比递降，极写受辱等次，突出腐刑为奇耻大辱，故下文引《记》“刑不上大夫”。","src":"报任安书"},{"q":"劳之来之，匡之直之，辅之翼之，使自得之，又从而振德之。","a":"慰劳他们，招揽他们，纠正他们，扶助他们，保护他们，使他们自得向善，又接着救济他们、对他们施恩德。","note":"振通\"赈\"，救济。写圣人忧民、教化之勤。","src":"许行"},{"q":"夫既已读之矣，而或口与躬违，心与迹忤，采其华而忘其实，是则呻占记诵之学所为哗众而窃名者也，与弗读奚以异哉！","a":"既然已经读了，但有的嘴上说的和亲身做的相违背，心里想的和实际做的相抵触，采摘它的花却忘了它的果，这就是那些吟哦记诵之学用来哗众取宠、盗取名声的东西，跟不读书又有什么不同呢！","note":"华实对举；奚以异：有何不同。批判脱离实践的记诵之学。","src":"传是楼记"}]},{"no":3,"date":"2026-10-31","date_end":"2026-11-01","pieces":["巫山巫峡","报任安书","吕相绝秦","许行","逍遥游","齐桓晋文之事"],"theme":"综合练习 3","p1":[{"q":"《许行》的作者是（　）","opts":["刘向","庄周","柳宗元","孟子"],"ans":"D","atext":"孟子","src":"篇目→作者","note":"《许行》：战国，孟子，选自《孟子·滕文公上》。"},{"q":"汪国真生活于（　）","opts":["北魏","当代","战国末期","秦代"],"ans":"B","atext":"当代","src":"人物→朝代","note":"汪国真，当代。"},{"q":"蔡襄生活于（　）","opts":["北宋","战国末期","北魏","春秋"],"ans":"A","atext":"北宋","src":"人物→朝代","note":"蔡襄，北宋。"},{"q":"《烛之武退秦师》的作者是（　）","opts":["孔子","庄周","孟子","左丘明"],"ans":"D","atext":"左丘明","src":"篇目→作者","note":"《烛之武退秦师》：春秋，左丘明，选自《左传·僖公三十年》。"},{"q":"《钴鉧潭西小丘记》选自（　）","opts":["战国策","史记","柳河东集","嘉祐集"],"ans":"C","atext":"柳河东集","src":"篇目→出处","note":"《钴鉧潭西小丘记》选自《柳河东集》（永州八记之三）。"},{"q":"卢照邻生活于（　）","opts":["初唐","西汉","战国末期","秦代"],"ans":"A","atext":"初唐","src":"人物→朝代","note":"卢照邻，初唐。"},{"q":"《邹忌讽齐王纳谏》的作者是（　）","opts":["孟子","庄周","荀子","刘向"],"ans":"D","atext":"刘向","src":"篇目→作者","note":"《邹忌讽齐王纳谏》：战国，刘向，选自《战国策·齐策一》。"},{"q":"陈独秀生活于（　）","opts":["北宋","现代","战国","秦代"],"ans":"B","atext":"现代","src":"人物→朝代","note":"陈独秀，现代。"},{"q":"胡适生活于（　）","opts":["西汉","战国末期","秦代","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"胡适，现代。"},{"q":"朱熹生活于（　）","opts":["北魏","南宋","战国末期","北宋"],"ans":"B","atext":"南宋","src":"人物→朝代","note":"朱熹，南宋。"},{"q":"骆宾王生活于（　）","opts":["秦代","北魏","初唐","战国"],"ans":"C","atext":"初唐","src":"人物→朝代","note":"骆宾王，初唐。"},{"q":"沙汀生活于（　）","opts":["北宋","战国","现代","战国末期"],"ans":"C","atext":"现代","src":"人物→朝代","note":"沙汀，现代。"},{"q":"汉乐府生活于（　）","opts":["战国末期","西汉","北魏","春秋"],"ans":"B","atext":"西汉","src":"人物→朝代","note":"汉乐府，西汉。"},{"q":"晏殊生活于（　）","opts":["春秋","北宋","战国末期","西汉"],"ans":"B","atext":"北宋","src":"人物→朝代","note":"晏殊，北宋。"},{"q":"《传是楼记》的作者是（　）","opts":["蒲松龄","李斯","晁错","汪琬"],"ans":"D","atext":"汪琬","src":"篇目→作者","note":"《传是楼记》：清，汪琬，选自《尧峰文钞》。"},{"q":"张炜生活于（　）","opts":["战国末期","当代","北宋","北魏"],"ans":"B","atext":"当代","src":"人物→朝代","note":"张炜，当代。"},{"q":"海子生活于（　）","opts":["当代","战国末期","战国","西汉"],"ans":"A","atext":"当代","src":"人物→朝代","note":"海子，当代。"},{"q":"姜夔生活于（　）","opts":["西汉","战国末期","南宋","北宋"],"ans":"C","atext":"南宋","src":"人物→朝代","note":"姜夔，南宋。"},{"q":"丰子恺生活于（　）","opts":["北宋","秦代","现代","西汉"],"ans":"C","atext":"现代","src":"人物→朝代","note":"丰子恺，现代。"},{"q":"郭沫若生活于（　）","opts":["现代","秦代","西汉","战国末期"],"ans":"A","atext":"现代","src":"人物→朝代","note":"郭沫若，现代。"}],"p2":[{"q":"「没死以闻」中「没死」的意思是（　）","opts":["等待","临时驻扎","冒死","甚、很"],"ans":"C","atext":"冒死","src":"实词释义","note":"《触龙说赵太后》没死以闻　没死：冒死罪，表恭敬；闻：使上级听到、禀告。"},{"q":"「倡优畜之」中「倡优」的意思是（　）","opts":["名词作状语，像乐工戏子一样","以往、从前（音nǎng）","通“仇”，仇敌","名词作状语，像鸟张开翅膀一样"],"ans":"A","atext":"名词作状语，像乐工戏子一样","src":"实词释义","note":"《报任安书》倡优畜之　被当作倡优一样畜养。"},{"q":"「绐公子奔拾之」中「绐」的意思是（　）","opts":["等待","满一年","欺骗","幼年"],"ans":"C","atext":"欺骗","src":"实词释义","note":"《小翠》绐公子奔拾之　绐（dài）：哄骗。"},{"q":"「鬻子孙以偿债」中「鬻」的意思是（　）","opts":["卖（音yù）","同“他”，别的","宽恕","通“智”，智慧"],"ans":"A","atext":"卖（音yù）","src":"实词释义","note":"《论贵粟疏》鬻子孙以偿债　与“卖”同义复用。"},{"q":"「而摩厉之于义」中「摩厉」的意思是（　）","opts":["错误、过失","戴帽子。","谦辞，犹“承蒙”","通“磨砺”，磨炼"],"ans":"D","atext":"通“磨砺”，磨炼","src":"实词释义","note":"《勾践灭吴》而摩厉之于义　摩厉通磨砺。"},{"q":"「吾与之共知越国之政」中「知」的意思是（　）","opts":["称量（轻重）。","主持，管理","常，永久固定的。","尽、全"],"ans":"B","atext":"主持，管理","src":"实词释义","note":"《勾践灭吴》吾与之共知越国之政　主持。"},{"q":"「尾闾泄之，不知何时已而不虚。」中「虚」的意思是（　）","opts":["（水）枯竭，减少。","遇合、际遇","通“隙”，隔阂、嫌怨","一天天地增多"],"ans":"A","atext":"（水）枯竭，减少。","src":"实词释义","note":"《秋水》尾闾泄之，不知何时已而不虚。　虚：空，指海水减少。"},{"q":"「以事秦之心礼天下之奇才」中「礼」的意思是（　）","opts":["以礼相待","攻取、占领","怎么，哪里","挫败、屈辱"],"ans":"A","atext":"以礼相待","src":"实词释义","note":"《六国论》以事秦之心礼天下之奇才　礼：名词活用为动词。"},{"q":"「端章甫，愿为小相焉」中「端章甫」的意思是（　）","opts":["能施展才能就任职，不能就辞职","成年人（古男子二十岁行冠礼）","穿着礼服、戴着礼帽","黑色染料黑泥（音niè）"],"ans":"C","atext":"穿着礼服、戴着礼帽","src":"实词释义","note":"《子路曾皙冉有公西华侍坐》端章甫，愿为小相焉　端：礼服名；章甫：礼帽名；皆名词活用为动词。"},{"q":"「如其礼乐，以俟君子」中「俟」的意思是（　）","opts":["等待","沿着","出使的人","满足"],"ans":"A","atext":"等待","src":"实词释义","note":"《子路曾皙冉有公西华侍坐》如其礼乐，以俟君子　至于礼乐教化，只能等待君子来施行。"}],"p3":[{"q":"春冬之时，则素湍绿潭，回清倒影。","a":"春冬季节，白色的急流、碧绿的深潭，回旋的清波倒映着山石林木的影子。","note":"素湍：白色急流；回清：回旋的清波。一句之中动静、色彩相映。","src":"巫山巫峡"},{"q":"所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后世也。","a":"我所以暗暗忍受、苟且活下来，被囚禁在污秽之地而不肯死，是遗憾自己心愿未了，怕默默无闻而死，文章才华不能显露于后世。","note":"“所以……者，……也”表原因判断；“恨”遗憾。点明忍辱著书之志。","src":"报任安书"},{"q":"秦大夫不询于我寡君，擅及郑盟。","a":"秦国大夫不征询我们国君意见，擅自与郑国订盟。","note":"询：问。指责秦背晋私盟郑。","src":"吕相绝秦"},{"q":"当尧之时，天下犹未平，洪水横流，泛滥于天下。","a":"在尧的时候，天下还不安定，洪水横流，泛滥于天下。","note":"极言尧时之忧患，说明圣人劳心治水、教化。","src":"许行"},{"q":"且夫水之积也不厚，则其负大舟也无力。覆杯水于坳堂之上，则芥为之舟。置杯焉则胶，水浅而舟大也。风之积也不厚，则其负大翼也无力。故九万里则风斯在下矣，而后乃今培风；背负青天而莫之夭阏者，而后乃今将图南。","a":"再说水的积聚不深厚，那么它负载大船就没有力量。倒一杯水在堂上低洼处，那么一根小草浮在上面就成了船；放上一只杯子就粘住不动了，这是水太浅而船太大的缘故。风的积聚不深厚，那么它负载巨大的翅膀就没有力量。所以大鹏飞上九万里高空，风就在它的下面了，然后才凭借风力；背负青天而没有什么阻碍它，然后才打算往南飞。","note":"坳堂：堂上低洼处；芥：小草；胶：粘住；夭阏：阻碍；培风：凭借风力；「莫之夭阏」宾语前置。","src":"逍遥游"},{"q":"曰：\"然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。海内之地，方千里者九，齐集有其一；以一服八，何以异于邹敌楚哉？盖亦反其本矣。今王发政施仁，使天下仕者皆欲立于王之朝，耕者皆欲耕于王之野，商贾皆欲藏于王之市，行旅皆欲出于王之涂，天下之欲疾其君者，皆欲赴愬于王；其若是，孰能御之？\"","a":"孟子说：\"那么小国本来不可以抵挡大国，人口少的本来不可以抵挡人口多的，弱国本来不可以抵挡强国。四海之内，方圆千里的共有九份，齐国聚拢起来只占其中一份；凭一份去征服八份，这和邹国抵挡楚国有什么不同呢？何不回到根本上呢。如今大王发布政令、施行仁政，使天下做官的人都想到大王的朝廷上任职，耕田的人都想到大王的田野里耕种，商人都想到大王的市场上做买卖，旅客都想取道大王的道路，天下痛恨自己君主的人都想到大王这里来申诉；如果这样，谁能抵挡呢？\"","note":"固：本来；集：凑集、聚拢；盖：通「盍」，何不；涂：通「途」，道路；愬：通「诉」，申诉。","src":"齐桓晋文之事"},{"q":"怒而飞，其翼若垂天之云。","a":"（鹏）振翅奋起而飞，它的翅膀就像天边垂下的云。","note":"怒：奋发；垂天：天边。以夸张比喻写鹏翼之大，为下文\"小大之辩\"张本。","src":"逍遥游"},{"q":"泾流之大，两涘渚崖之间，不辩牛马。","a":"水流宽阔，两岸和水中沙洲之间，连牛马都分辨不清。","note":"辩通\"辨\"。极写河水之大，为河伯\"以天下之美为尽在己\"张本。","src":"秋水"},{"q":"范增数目项王，举所佩玉玦以示之者三，项王默然不应。","a":"范增多次向项王使眼色，再三举起所佩戴的玉玦暗示项王，项王沉默着没有反应。","note":"“目”名词作动词，递眼色；“三”多次。写范增暗示刺杀而项羽犹豫。","src":"鸿门宴"},{"q":"燕、赵、韩、魏闻之，皆朝于齐。","a":"燕、赵、韩、魏四国听到这件事，都来齐国朝见。","note":"“朝于齐”状语后置，即“于齐朝”；“朝”读cháo，朝见。","src":"邹忌讽齐王纳谏"},{"q":"上下相反，好恶乖迕，而欲国富法立，不可得也。","a":"上下相反，爱好和厌恶相违背，却想要国家富强、法律建立，是不可能的。","note":"“乖迕”违背。总结重农抑商政策名实不符之弊。","src":"论贵粟疏"},{"q":"孔子曰：“求！君子疾夫舍曰欲之而必为之辞。丘也闻有国有家者，不患寡而患不均，不患贫而患不安。盖均无贫，和无寡，安无倾。夫如是，故远人不服，则修文德以来之。既来之，则安之。今由与求也，相夫子，远人不服而不能来也；邦分崩离析而不能守也；而谋动干戈于邦内。吾恐季孙之忧，不在颛臾，而在萧墙之内也。”","a":"孔子说：\"冉求！君子痛恨那种不说自己想要却一定要另找借口的态度。我听说拥有国家的诸侯和拥有采邑的卿大夫，不担心贫穷而担心分配不均，不担心人口少而担心不安定。因为平均就不会贫穷，和睦就不会觉得人少，安定就不会倾覆。像这样，所以远方的人不归服，就修治文教德政来使他们归附。使他们来了，就要使他们安定。如今仲由和冉求你们两个人辅佐季氏，远方的人不归服却不能使他们来归；国家分崩离析却不能保全；反而想在国境之内发动战争。我恐怕季孙氏的忧患，不在颛臾，而在宫墙之内啊。\"","note":"疾：痛恨；辞：托辞、借口；患：担忧；均无贫：分配平均就不觉得贫穷；萧墙：宫门内屏风，指内部。","src":"季氏将伐颛臾"},{"q":"太后之色少解。","a":"太后的怒色稍微消解了些。","note":"少：稍微；解：消解。侧面写进谏初见成效。","src":"触龙说赵太后"},{"q":"且燕、赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。","a":"况且燕赵两国正处在秦国把其他国家几乎消灭干净的时候，可以说是智谋穷竭、势力孤单，战败而亡，实在是不得已。","note":"智力：智谋和力量（古今异义）；诚：实在。为燕赵辩护。","src":"六国论"},{"q":"元和二年四月十三日夜，愈与吴郡张籍阅家中旧书，得李翰所为《张巡传》。翰以文章自名，为此传颇详密。然尚恨有阙者：不为许远立传，又不载雷万春事首尾。","a":"元和二年四月十三日夜晚，我和吴郡张籍翻阅家中旧书，看到李翰所作的《张巡传》。李翰以文章自负，写这篇传颇为详尽周密。但还遗憾有缺漏：没有给许远立传，又没有记载雷万春事迹的始末。","note":"自名：自负、自称；恨：遗憾；阙：通「缺」，缺漏。","src":"张中丞传后叙"},{"q":"为文章，操纸笔立书，未尝起草。","a":"写起文章来，拿起纸笔立刻写成，从不打草稿。","note":"操：拿；立书：立刻写就。侧面写张巡之才。","src":"张中丞传后叙"},{"q":"今媪尊长安君之位，而封之以膏腴之地。","a":"现在您使长安君地位尊贵，把肥沃的土地封给他。","note":"尊：使动；“封之以膏腴之地”状语后置，即“以膏腴之地封之”。","src":"触龙说赵太后"},{"q":"姜氏何厌之有？不如早为之所，无使滋蔓。","a":"姜氏有什么满足的？不如及早给他安排个地方，不要让他的势力滋长蔓延。","note":"“何厌之有”即“有何厌”，“之”为宾语前置标志；厌通餍。","src":"郑伯克段于鄢"},{"q":"且君尝为晋君赐矣，许君焦、瑕，朝济而夕设版焉。","a":"况且您曾对晋惠公施过恩惠，他答应给您焦、瑕两城，可早上渡河回国，晚上就筑城拒秦。","note":"揭晋忘恩无信。设版：筑城墙（防御）。","src":"烛之武退秦师"},{"q":"此其自多也，不似尔向之自多于水乎？","a":"他们这样自我夸耀，不就像你先前因河水上涨而自满一样吗？","note":"向：先前。收束本段，点戒矜夸自多之旨。","src":"秋水"}]},{"no":4,"date":"2026-11-01","date_end":"2026-11-02","pieces":["齐桓公伐楚","勾践灭吴","烛之武退秦师","谏逐客书","许行","触龙说赵太后"],"theme":"综合练习 4","p1":[{"q":"范晔生活于（　）","opts":["战国末期","春秋","秦代","南北朝"],"ans":"D","atext":"南北朝","src":"人物→朝代","note":"范晔，南北朝。"},{"q":"陶渊明生活于（　）","opts":["东晋","秦代","西汉","战国末期"],"ans":"A","atext":"东晋","src":"人物→朝代","note":"陶渊明，东晋。"},{"q":"汪曾祺生活于（　）","opts":["秦代","北宋","当代","北魏"],"ans":"C","atext":"当代","src":"人物→朝代","note":"汪曾祺，当代。"},{"q":"《触龙说赵太后》选自（　）","opts":["聊斋志异","国语","尧峰文钞","战国策"],"ans":"D","atext":"战国策","src":"篇目→出处","note":"《触龙说赵太后》选自《战国策·赵策四》。"},{"q":"吴强生活于（　）","opts":["战国","当代","西汉","北宋"],"ans":"B","atext":"当代","src":"人物→朝代","note":"吴强，当代。"},{"q":"《吕相绝秦》选自（　）","opts":["聊斋志异","左传","史记","嘉祐集"],"ans":"B","atext":"左传","src":"篇目→出处","note":"《吕相绝秦》选自《左传·成公十三年》。"},{"q":"毕飞宇生活于（　）","opts":["北魏","北宋","当代","秦代"],"ans":"C","atext":"当代","src":"人物→朝代","note":"毕飞宇，当代。"},{"q":"艾青生活于（　）","opts":["北宋","战国末期","现代","北魏"],"ans":"C","atext":"现代","src":"人物→朝代","note":"艾青，现代。"},{"q":"李煜生活于（　）","opts":["南唐","战国末期","北魏","秦代"],"ans":"A","atext":"南唐","src":"人物→朝代","note":"李煜，南唐。"},{"q":"《张中丞传后叙》选自（　）","opts":["苏轼文集","国语","韩昌黎集","尧峰文钞"],"ans":"C","atext":"韩昌黎集","src":"篇目→出处","note":"《张中丞传后叙》选自《韩昌黎集》。"},{"q":"路遥生活于（　）","opts":["战国","北宋","北魏","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"路遥，当代。"},{"q":"王小波生活于（　）","opts":["当代","北宋","战国末期","战国"],"ans":"A","atext":"当代","src":"人物→朝代","note":"王小波，当代。"},{"q":"张贤亮生活于（　）","opts":["当代","北宋","北魏","秦代"],"ans":"A","atext":"当代","src":"人物→朝代","note":"张贤亮，当代。"},{"q":"司马彪生活于（　）","opts":["北宋","西晋","战国","战国末期"],"ans":"B","atext":"西晋","src":"人物→朝代","note":"司马彪，西晋。"},{"q":"曲波生活于（　）","opts":["战国末期","北魏","当代","秦代"],"ans":"C","atext":"当代","src":"人物→朝代","note":"曲波，当代。"},{"q":"《逍遥游》选自（　）","opts":["水经注","嘉祐集","韩昌黎集","庄子"],"ans":"D","atext":"庄子","src":"篇目→出处","note":"《逍遥游》选自《庄子·内篇·逍遥游》。"},{"q":"巴金生活于（　）","opts":["现代","战国","西汉","战国末期"],"ans":"A","atext":"现代","src":"人物→朝代","note":"巴金，现代。"},{"q":"三毛生活于（　）","opts":["北魏","秦代","当代","北宋"],"ans":"C","atext":"当代","src":"人物→朝代","note":"三毛，当代。"},{"q":"诗歌生活于（　）","opts":["战国末期","西汉","先秦","春秋"],"ans":"C","atext":"先秦","src":"人物→朝代","note":"诗歌，先秦。"},{"q":"周敦颐生活于（　）","opts":["战国末期","春秋","秦代","北宋"],"ans":"D","atext":"北宋","src":"人物→朝代","note":"周敦颐，北宋。"}],"p2":[{"q":"「朝服衣冠」中「服」的意思是（　）","opts":["穿戴","通“娶","求，求取","通“婚”"],"ans":"A","atext":"穿戴","src":"实词释义","note":"《邹忌讽齐王纳谏》朝服衣冠　服：名词衣服活用为动词“穿戴”。"},{"q":"「木直中绳」中「中」的意思是（　）","opts":["符合、合乎（音zhòng）","趋向、追求（音qū）","浸泡、沾染（音jiān）","承受、经得起（音shēng）"],"ans":"A","atext":"符合、合乎（音zhòng）","src":"实词释义","note":"《劝学》木直中绳　动词；下句“其曲中规”同。"},{"q":"「姜氏欲之，焉辟害」中「焉」的意思是（　）","opts":["何、怎么","怎么，哪里","痛恨、讨厌","那个人，指秦穆公"],"ans":"B","atext":"怎么，哪里","src":"实词释义","note":"《郑伯克段于鄢》姜氏欲之，焉辟害　疑问代词作状语。"},{"q":"「微夫人之力不及此」中「微」的意思是（　）","opts":["满足","没有","穿戴","封侯"],"ans":"B","atext":"没有","src":"实词释义","note":"《烛之武退秦师》微夫人之力不及此　表假设的否定连词。"},{"q":"「向使四君却客而不内」中「内」的意思是（　）","opts":["通“纳”，接纳","交换、购置","通“阵”，列阵","兼词，相当于“于此”"],"ans":"A","atext":"通“纳”，接纳","src":"实词释义","note":"《谏逐客书》向使四君却客而不内　“内”读nà，通“纳”。"},{"q":"「江水又东，径巫峡」中「东」的意思是（　）","opts":["到、往","饱、满足","冒死","向东"],"ans":"D","atext":"向东","src":"实词释义","note":"《巫山巫峡》江水又东，径巫峡　方位名词“东”直接修饰动词“径”，作状语。"},{"q":"「疑畏死而辞服于贼」中「辞服」的意思是（　）","opts":["通“疲”，疲弱无能","出言屈服、投降","检验、检查（音cān）","敬重和取法"],"ans":"B","atext":"出言屈服、投降","src":"实词释义","note":"《张中丞传后叙》疑畏死而辞服于贼　辞：陈辞；服：屈服。"},{"q":"「去以六月息者也。」中「息」的意思是（　）","opts":["气息，这里指六月的大风（海风）。","如，比得上（动词）。","通\"返\"，返回。","按时，按季节。"],"ans":"A","atext":"气息，这里指六月的大风（海风）。","src":"实词释义","note":"《逍遥游》去以六月息者也。　乘六月海动之风而南飞。"},{"q":"「移时晴霁」中「霁」的意思是（　）","opts":["堵塞、杜绝","雨过天晴","聚集","坚持正义"],"ans":"B","atext":"雨过天晴","src":"实词释义","note":"《小翠》移时晴霁　霁（jì）：天晴。"},{"q":"「以千百就尽之卒」中「就尽」的意思是（　）","opts":["延续、遍及（音yì）","渐趋覆没、将要死尽","名词作动词，游水、游泳","违背、相反（迕wǔ）"],"ans":"B","atext":"渐趋覆没、将要死尽","src":"实词释义","note":"《张中丞传后叙》以千百就尽之卒　就：接近。"}],"p3":[{"q":"贡之不入，寡君之罪也，敢不共给？","a":"贡品不交纳，是我们国君的罪过，怎敢不供给？","note":"判断句“……也”；共通供。楚使只认包茅之罪。","src":"齐桓公伐楚"},{"q":"越人饰美女八人，纳之太宰嚭，曰：“子苟赦越国之罪，又有美于此者将进之。”太宰嚭谏曰：“嚭闻古之伐国者，服之而已；今已服矣，又何求焉？”夫差与之成而去之。","a":"越国人打扮了八个美女，送给太宰伯嚭，说：\"您如果赦免越国的罪过，还有比这些更美的将进献给您。\"太宰伯嚭劝谏说：\"我听说古代讨伐别国的，使它降服就罢了；如今越国已经降服了，还要求什么呢？\"夫差就和越国讲和，撤兵离开了。","note":"纳：送给；进：进献；服：使……降服；成：讲和；去之：撤离。","src":"勾践灭吴"},{"q":"若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。","a":"如果放过郑国让它做东方道路上的主人，秦国使者往来，郑国可供应他们缺的资粮，对您也无害。","note":"东道主：东方道上的主人；行李：使者；共通供。","src":"烛之武退秦师"},{"q":"臣闻吏议逐客，窃以为过矣。","a":"我听说官吏们商议驱逐客卿，私下认为这是错误的。","note":"开篇单刀直入提出中心论点；“窃”表自谦。全文以此断语统领。","src":"谏逐客书"},{"q":"远方之人闻君行仁政，愿受一廛而为氓。","a":"我这远方之人听说您施行仁政，希望得到一处住所做您的百姓。","note":"廛：一夫之居；氓：外来之民。","src":"许行"},{"q":"老臣以媪为长安君计短也，故以为其爱不若燕后。","a":"我认为您为长安君打算得太短浅了，所以觉得您爱他不如爱燕后。","note":"以……为：认为……；“不若”：不如、比不上。","src":"触龙说赵太后"},{"q":"然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。","a":"那么小国本来不可与大国为敌，人少之国本来不可与人多之国为敌，弱国本来不可与强国为敌。","note":"小、大、寡、众、弱、强均形容词作名词。三组排比。","src":"齐桓晋文之事"},{"q":"是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。","a":"所以没有精诚专一意志的人，就不会有明察的智慧；没有埋头苦干实事的人，就不会有显赫的功业。","note":"“冥冥”“惛惛”专心一意；“昭昭”“赫赫”显明显赫。对偶句强调专一笃实。","src":"劝学"},{"q":"观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。","a":"考察汉高祖之所以胜利、项羽之所以失败的原因，就在于能忍与不能忍之间罢了。","note":"项籍：项羽。以刘项成败立论，归结到“忍”字。","src":"留侯论"},{"q":"古人云：“以地事秦，犹抱薪救火，薪不尽，火不灭。”","a":"古人说：“用土地侍奉秦国，就好像抱着柴草去救火，柴草不烧完，火就不会灭。”","note":"事：侍奉。引古人作喻，形象说明赂秦之非。","src":"六国论"},{"q":"此数宝者，秦不生一焉，而陛下说之，何也？","a":"这几样宝物，秦国一样都不出产，可是陛下却喜爱它们，为什么呢？","note":"“说”通“悦”。以物设喻，转入今陛下重物轻人之论。","src":"谏逐客书"},{"q":"多行不义必自毙，子姑待之。","a":"多做不义的事，一定会自取灭亡，您姑且等着吧。","note":"毙：仆倒、灭亡。庄公知段必叛而故意纵容。","src":"郑伯克段于鄢"},{"q":"吾入关，秋毫不敢有所近，籍吏民，封府库，而待将军。","a":"我入关后，一点东西都不敢沾边，登记官吏百姓，封闭府库，等待将军到来。","note":"“秋毫”比喻极细小之物；“籍”名词作动词，登记。向项伯表忠心。","src":"鸿门宴"},{"q":"夫人情莫不贪生恶死，念父母，顾妻子。至激于义理者不然，乃有所不得已也。今仆不幸，早失父母，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？且勇者不必死节，怯夫慕义，何处不勉焉？仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后世也。","a":"人之常情没有不贪生怕死、思念父母、顾念妻子儿女的。至于被义理激奋的人却不是这样，是有不得已的地方。如今我不幸，早年失去父母，没有兄弟的亲近，孤身一人，少卿您看我对于妻子儿女怎么样呢？况且勇敢的人不一定为节义而死，怯懦的人仰慕道义，哪里不能勉励自己呢？我虽然怯懦，想苟且活命，也很懂得去就的分寸，怎么会至于自己沉溺于牢狱的耻辱呢！之所以隐忍苟活，幽居于污秽之中而不推辞，是遗憾内心有未了的心愿，平庸地死去，而文采不能显扬于后世。","note":"去就之分：该去该留的分寸；缧绁：捆绑犯人的绳索，代指牢狱；没世：终身、死去；文采不表：文采不能显扬。","src":"报任安书"},{"q":"敢尽布之执事，俾执事实图利之！","a":"冒昧地把这些全部陈述给您，请您认真考虑对秦有利的做法！","note":"敢：谦辞冒昧；布：陈述；图：考虑。绝交书的结束语。","src":"吕相绝秦"},{"q":"当淮阴破齐而欲自王，高祖发怒，见于词色。由此观之，犹有刚强不忍之气，非子房其谁全之？","a":"当韩信攻破齐国想自立为王时，高祖发怒，怒气显露在言辞脸色上。由此看来，高祖还有刚强不能忍耐的脾气，不是张良谁能成全他呢？","note":"王（wàng）：称王；见（xiàn）：流露。举例说明张良教高祖以忍。","src":"留侯论"},{"q":"夏，楚子使屈完如师。师退，次于召陵。齐侯陈诸侯之师，与屈完乘而观之。齐侯曰：“岂不穀是为？先君之好是继，与不穀同好，如何？”对曰：“君惠徼福于敝邑之社稷，辱收寡君，寡君之愿也。”齐侯曰：“以此众战，谁能御之！以此攻城，何城不克！”对曰：“君若以德绥诸侯，谁敢不服？君若以力，楚国方城以为城，汉水以为池，虽众，无所用之！”","a":"夏天，楚成王派屈完到诸侯军中。诸侯军队后撤，驻扎在召陵。齐桓公把诸侯的军队列成阵势，和屈完同乘一辆车观看。桓公说：\"难道是为了我吗？不过是为了继续先君的友好关系，和我共同友好，怎么样？\"屈完回答说：\"承蒙您为敝国社稷求福，屈尊接纳我们国君，这是我们国君的愿望。\"桓公说：\"用这样的军队作战，谁能抵挡？用这样的军队攻城，哪座城攻不下？\"屈完回答说：\"您如果用德行安抚诸侯，谁敢不服？您如果凭借武力，楚国以方城山为城墙，以汉水为护城河，您军队虽多，也没有用处！\"","note":"如：往、到；次：驻扎；不穀：诸侯自称谦词；徼福：求福；绥：安抚。","src":"齐桓公伐楚"},{"q":"盖文王拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》。","a":"周文王被拘禁而推演《周易》；孔子受困厄而写作《春秋》；屈原被放逐，才创作出《离骚》。","note":"排比句；“拘”“厄”“放逐”皆被动意味。连串史例论证发愤著书。","src":"报任安书"},{"q":"人方蹈我之瑕，反以闺阁之丑登门而告之，余祸不远矣！","a":"人家正要抓我的把柄，我倒把闺房中的丑事上门去告诉他，我的祸事不远了！","note":"蹈瑕：利用过失。写王公的忧虑。","src":"小翠"},{"q":"燕、赵之君，始有远略，能守其土，义不赂秦。","a":"燕国和赵国的君主，起初有长远的谋略，能够守住他们的国土，坚持正义，不贿赂秦国。","note":"义：名词作状语，坚持正义。肯定燕赵守土抗秦。","src":"六国论"}]},{"no":5,"date":"2026-11-02","date_end":"2026-11-03","pieces":["六国论","吕相绝秦","小翠","逍遥游","劝学","邹忌讽齐王纳谏"],"theme":"综合练习 5","p1":[{"q":"《逍遥游》的作者是（　）","opts":["孟子","刘向","荀子","庄周"],"ans":"D","atext":"庄周","src":"篇目→作者","note":"《逍遥游》：战国，庄周，选自《庄子·内篇·逍遥游》。"},{"q":"史铁生生活于（　）","opts":["北宋","战国","当代","秦代"],"ans":"C","atext":"当代","src":"人物→朝代","note":"史铁生，当代。"},{"q":"胡铨生活于（　）","opts":["秦代","南宋","西汉","战国末期"],"ans":"B","atext":"南宋","src":"人物→朝代","note":"胡铨，南宋。"},{"q":"莫言生活于（　）","opts":["当代","西汉","战国","秦代"],"ans":"A","atext":"当代","src":"人物→朝代","note":"莫言，当代。"},{"q":"白先勇生活于（　）","opts":["战国","当代","战国末期","西汉"],"ans":"B","atext":"当代","src":"人物→朝代","note":"白先勇，当代。"},{"q":"李金发生活于（　）","opts":["战国","北宋","北魏","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"李金发，现代。"},{"q":"杨炯生活于（　）","opts":["初唐","北魏","北宋","西汉"],"ans":"A","atext":"初唐","src":"人物→朝代","note":"杨炯，初唐。"},{"q":"李大钊生活于（　）","opts":["战国末期","战国","北魏","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"李大钊，现代。"},{"q":"叶紫生活于（　）","opts":["秦代","现代","战国末期","西汉"],"ans":"B","atext":"现代","src":"人物→朝代","note":"叶紫，现代。"},{"q":"韩少功生活于（　）","opts":["当代","战国","北魏","战国末期"],"ans":"A","atext":"当代","src":"人物→朝代","note":"韩少功，当代。"},{"q":"秦观生活于（　）","opts":["秦代","春秋","北宋","战国末期"],"ans":"C","atext":"北宋","src":"人物→朝代","note":"秦观，北宋。"},{"q":"拓展生活于（　）","opts":["战国","战国末期","春秋","先秦"],"ans":"D","atext":"先秦","src":"人物→朝代","note":"拓展，先秦。"},{"q":"孔子生活于（　）","opts":["战国末期","春秋","秦代","战国"],"ans":"B","atext":"春秋","src":"人物→朝代","note":"孔子，春秋。"},{"q":"丁玲生活于（　）","opts":["现代","战国末期","北魏","西汉"],"ans":"A","atext":"现代","src":"人物→朝代","note":"丁玲，现代。"},{"q":"百家争鸣生活于（　）","opts":["北宋","战国末期","春秋","战国"],"ans":"D","atext":"战国","src":"人物→朝代","note":"百家争鸣，战国。"},{"q":"阿城生活于（　）","opts":["西汉","北魏","当代","北宋"],"ans":"C","atext":"当代","src":"人物→朝代","note":"阿城，当代。"},{"q":"杨沫生活于（　）","opts":["西汉","当代","北宋","战国末期"],"ans":"B","atext":"当代","src":"人物→朝代","note":"杨沫，当代。"},{"q":"刘慈欣生活于（　）","opts":["战国末期","秦代","战国","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"刘慈欣，当代。"},{"q":"两汉生活于（　）","opts":["战国","春秋","战国末期","西汉"],"ans":"D","atext":"西汉","src":"人物→朝代","note":"两汉，西汉。"},{"q":"余光中生活于（　）","opts":["当代","北宋","西汉","北魏"],"ans":"A","atext":"当代","src":"人物→朝代","note":"余光中，当代。"}],"p2":[{"q":"「将其创残饿羸之余」中「将」的意思是（　）","opts":["保全","用杖打","责备","率领"],"ans":"D","atext":"率领","src":"实词释义","note":"《张中丞传后叙》将其创残饿羸之余　用作动词，带领。"},{"q":"「如五六十」中「如」的意思是（　）","opts":["或者","迎接","出卖","飞奔的马"],"ans":"A","atext":"或者","src":"实词释义","note":"《子路曾皙冉有公西华侍坐》如五六十　表选择：或者五六十里。"},{"q":"「江水又东，径巫峡」中「径」的意思是（　）","opts":["倾覆","值得爱惜","行走","经过"],"ans":"D","atext":"经过","src":"实词释义","note":"《巫山巫峡》江水又东，径巫峡　“径”本义小路，此活用为动词“经过、取道”。"},{"q":"「泾流之大，两涘渚崖之间，不辩牛马。」中「泾」的意思是（　）","opts":["直流的水，河面水流。","主持，管理","做贵族的仆役","名词作动词，称王（音wàng）"],"ans":"A","atext":"直流的水，河面水流。","src":"实词释义","note":"《秋水》泾流之大，两涘渚崖之间，不辩牛马。　泾(jīng)流：直通无阻的水流。"},{"q":"「其次诎体受辱」中「诎」的意思是（　）","opts":["率领，带着","通“屈”，弯曲、屈曲","通“煣”，用火烤木材使之弯曲","放大火烧。"],"ans":"B","atext":"通“屈”，弯曲、屈曲","src":"实词释义","note":"《报任安书》其次诎体受辱　“诎”通“屈”，谓被捆绑。"},{"q":"「君子博学而日参省乎己」中「日」的意思是（　）","opts":["肃杀、凄清","通\"诉\"，申诉，控诉。","名词作状语，每天","投，落下，跌落。"],"ans":"C","atext":"名词作状语，每天","src":"实词释义","note":"《劝学》君子博学而日参省乎己　时间名词作状语，表经常性。"},{"q":"「则将焉用彼相矣」中「相」的意思是（　）","opts":["在公众场合指责、议论（讥：谏）","扶助盲人的人，此指辅佐者","名词作动词，从事农业生产","修理、整治（此指修缮官府）"],"ans":"B","atext":"扶助盲人的人，此指辅佐者","src":"实词释义","note":"《季氏将伐颛臾》则将焉用彼相矣　相（xiàng）：扶相；下文“相夫子”的“相”为动词“辅佐”。"},{"q":"「而或口与躬违，心与迹忤」中「忤」的意思是（　）","opts":["研究，奉行。","通“嗜”，喜爱","损害，剥削。","违背、抵触"],"ans":"D","atext":"违背、抵触","src":"实词释义","note":"《传是楼记》而或口与躬违，心与迹忤　忤（wǔ）：不合。"},{"q":"「莫春者」中「莫」的意思是（　）","opts":["恐怕，莫非（表推测）","通“暮”，晚","这里指有战事、用兵","通“悦”，喜悦、喜爱"],"ans":"B","atext":"通“暮”，晚","src":"实词释义","note":"《子路曾皙冉有公西华侍坐》莫春者　莫春：暮春，阴历三月。"},{"q":"「是社稷之臣也」中「社稷」的意思是（　）","opts":["木杖荆条，古代刑具，指拷打","形容词作动词，交好、友善","安详镇定、若无其事的样子","土神谷神，代指国家"],"ans":"D","atext":"土神谷神，代指国家","src":"实词释义","note":"《季氏将伐颛臾》是社稷之臣也　此句为判断句。"}],"p3":[{"q":"有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。","a":"有这样有利的形势，却被秦国积久的威势所挟制，一天天地削减、一月月地割让，而走向灭亡。","note":"为……所：被动句式；日、月：名词作状语。沉痛总结历史教训。","src":"六国论"},{"q":"而欲徼福于先君献、穆。","a":"您施恩求福于我们先君献公、穆公。","note":"徼（yāo）：求。秦侯后悔战祸蔓延，想求福于晋先君献、穆，重结旧好。","src":"吕相绝秦"},{"q":"生一子名元丰，绝痴，十六岁不能知牝牡，因而乡党无与为婚。","a":"生了一个儿子名叫元丰，痴呆到极点，十六岁还不懂男女之事，因此乡里没有人肯同他家结亲。","note":"牝牡：雌雄，指男女。交代小翠嫁痴儿的缘由。","src":"小翠"},{"q":"夫列子御风而行，泠然善也，旬有五日而后反。彼于致福者，未数数然也。此虽免乎行，犹有所待者也。","a":"列子驾着风飞行，轻飘飘地十分轻妙，过了十五天才返回。他对于求福的事，并不急切追求。这样虽然免于步行，但还是有所凭借的。","note":"御：驾；泠然：轻妙的样子；旬有五日：十五天，「有」通「又」；反：通「返」；数数然：急切追求；待：凭借。","src":"逍遥游"},{"q":"吾尝终日而思矣，不如须臾之所学也。","a":"我曾经整天地思索，却比不上片刻学习的收获大。","note":"“而”连词表修饰；“须臾”片刻。对比“思”与“学”，强调学重于思。","src":"劝学"},{"q":"王曰：“善。”乃下令：“群臣吏民能面刺寡人之过者，受上赏；上书谏寡人者，受中赏；能谤讥于市朝，闻寡人之耳者，受下赏。”令初下，群臣进谏，门庭若市；数月之后，时时而间进；期年之后，虽欲言，无可进者。燕、赵、韩、魏闻之，皆朝于齐。此所谓战胜于朝廷。","a":"齐威王说：\"好。\"于是下令：\"群臣、官吏、百姓能够当面指责我的过错的，受上等奖赏；上书劝谏我的，受中等奖赏；能够在公共场所批评议论我的过失、传到我耳朵里的，受下等奖赏。\"命令刚下达时，群臣都来进谏，宫门庭院像集市一样热闹；几个月以后，还时时有人偶尔进谏；满一年以后，即使想进谏，也没有什么可说的了。燕国、赵国、韩国、魏国听说了这件事，都到齐国来朝见。这就是人们所说的在朝廷上战胜别国。","note":"面刺：当面指责；谤讥：议论批评；间进：偶尔进谏；期年：满一年；战胜于朝廷：状语后置。","src":"邹忌讽齐王纳谏"},{"q":"此所谓战胜于朝廷。","a":"这就是所说的在朝廷上战胜敌国。","note":"判断句（“此所谓……”）；“战胜于朝廷”状语后置，即“于朝廷战胜”，指内政修明不必用兵即可使敌国畏服。","src":"邹忌讽齐王纳谏"},{"q":"君若以力，楚国方城以为城，汉水以为池，虽众，无所用之！","a":"您如果动用武力，楚国有方城山作城墙，汉水作护城河，您的军队虽多，也用不上！","note":"“方城以为城，汉水以为池”宾语前置（以方城为城）。刚柔并济，不卑不亢。","src":"齐桓公伐楚"},{"q":"嘉木立，美竹露，奇石显。","a":"美好的树木挺立起来，秀美的竹子显露出来，奇峭的石头显现出来。","note":"立、露、显三个动词写整治后的变化，一字一顿。","src":"钴鉧潭西小丘记"},{"q":"故推恩足以保四海，不推恩无以保妻子。","a":"所以推广恩德足以安定天下，不推广恩德连妻子儿女都保全不了。","note":"妻子：古今异义，妻子和儿女。对比说推恩之效。","src":"齐桓晋文之事"},{"q":"勤苦如此，尚复被水旱之灾，急政暴赋，赋敛不时，朝令而暮当具。","a":"勤劳辛苦到这种地步，还要遭受水旱灾害，赋税又急迫暴虐，征收不按时节，早晨下命令晚上就要备齐。","note":"“被”遭受；“不时”不按时节；“朝令暮当具”极言赋税之急。","src":"论贵粟疏"},{"q":"大隧之中，其乐也融融！","a":"走进大隧之中，那快乐啊和暖融洽！","note":"融融：和乐貌。郑庄公入隧赋诗。","src":"郑伯克段于鄢"},{"q":"曲士不可以语于道者，束于教也。","a":"见识浅陋的人不能和他谈大道，是因为他被所受教养束缚。","note":"判断句；曲士：乡曲之士。三者由空间、时间、教养三层写局限。","src":"秋水"},{"q":"一旦山陵崩，长安君何以自托于赵？","a":"一旦您去世，长安君凭什么在赵国立足呢？","note":"山陵崩：讳称太后死；“何以”宾语前置，即“以何”。","src":"触龙说赵太后"},{"q":"肉腐出虫，鱼枯生蠹。怠慢忘身，祸灾乃作。","a":"肉腐烂就生蛆，鱼干枯就长虫。懈怠疏忽忘乎自身，灾祸就会发生。","note":"“蠹”蛀虫；“作”兴起。比喻荣辱祸福皆由自身招致。","src":"劝学"},{"q":"文公躬擐甲胄，跋履山川，逾越险阻。","a":"文公亲自披甲戴盔，跋涉山川，越过艰难险阻。","note":"躬：亲自；擐（huàn）：穿。四字句排比，气势充沛。","src":"吕相绝秦"},{"q":"其间首尾百六十里，谓之巫峡，盖因山为名也。","a":"这之间首尾长一百六十里，叫做巫峡，大概是因为巫山而得名的。","note":"盖：句首语气词，表推测；因：介词，凭借。判断兼解释得名由来。","src":"巫山巫峡"},{"q":"吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求于我也。","a":"我妻子认为我美，是偏爱我；妾认为我美，是害怕我；客人认为我美，是有求于我。","note":"三个判断句排比，“……者，……也”表判断；“美”为意动用法，“私”为偏爱。","src":"邹忌讽齐王纳谏"},{"q":"以若所为，求若所欲，犹缘木而求鱼也。","a":"凭这样的做法，去追求这样的欲望，就像爬到树上去找鱼。","note":"缘：攀援。成语\"缘木求鱼\"所本，喻方向方法错，必无所获。","src":"齐桓晋文之事"},{"q":"夫寒之于衣，不待轻暖；饥之于食，不待甘旨；饥寒至身，不顾廉耻。人情，一日不再食则饥，终岁不制衣则寒。夫腹饥不得食，肤寒不得衣，虽慈母不能保其子，君安能以有其民哉！明主知其然也，故务民于农桑，薄赋敛，广畜积，以实仓廪，备水旱，故民可得而有也。","a":"人在寒冷时对衣服的要求，不会等到轻暖的才穿；饥饿时对食物的要求，不会等到甘美的才吃；饥寒临身，就不顾廉耻了。人之常情是：一天不吃两顿饭就饿，整年不添置衣服就冷。腹中饥饿得不到食物，身上寒冷得不到衣服，即使是慈母也不能保住她的孩子，君主又怎么能保有他的百姓呢！英明的君主知道这个道理，所以使百姓致力于农桑，减轻赋税，广泛积蓄，来充实粮仓，防备水旱灾害，因此百姓才能得到并保有。","note":"待：等到；甘旨：甜美；再食：吃两顿；保：保全；务民于农桑：使百姓致力于农桑，状语后置。","src":"论贵粟疏"}]},{"no":6,"date":"2026-11-03","date_end":"2026-11-04","pieces":["子路曾皙冉有公西华侍坐","小翠","传是楼记","报任安书","许行","郑伯克段于鄢"],"theme":"综合练习 6","p1":[{"q":"永嘉四灵生活于（　）","opts":["秦代","战国末期","北魏","南宋"],"ans":"D","atext":"南宋","src":"人物→朝代","note":"永嘉四灵，南宋。"},{"q":"散文集生活于（　）","opts":["战国","战国末期","秦代","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"散文集，当代。"},{"q":"萧红生活于（　）","opts":["战国末期","战国","现代","北魏"],"ans":"C","atext":"现代","src":"人物→朝代","note":"萧红，现代。"},{"q":"《秋水》选自（　）","opts":["柳河东集","庄子","韩昌黎集","尧峰文钞"],"ans":"B","atext":"庄子","src":"篇目→出处","note":"《秋水》选自《庄子·外篇·秋水》。"},{"q":"鲁迅生活于（　）","opts":["北宋","北魏","战国末期","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"鲁迅，现代。"},{"q":"贾谊生活于（　）","opts":["汉代","北魏","战国末期","战国"],"ans":"A","atext":"汉代","src":"人物→朝代","note":"贾谊，汉代。"},{"q":"李宝嘉生活于（　）","opts":["秦代","战国末期","清末","西汉"],"ans":"C","atext":"清末","src":"人物→朝代","note":"李宝嘉，清末。"},{"q":"张天翼生活于（　）","opts":["现代","战国末期","秦代","战国"],"ans":"A","atext":"现代","src":"人物→朝代","note":"张天翼，现代。"},{"q":"刘鹗生活于（　）","opts":["清末","战国末期","北宋","北魏"],"ans":"A","atext":"清末","src":"人物→朝代","note":"刘鹗，清末。"},{"q":"顾城生活于（　）","opts":["秦代","西汉","北魏","当代"],"ans":"D","atext":"当代","src":"人物→朝代","note":"顾城，当代。"},{"q":"《许行》选自（　）","opts":["国语","苏轼文集","孟子","论语"],"ans":"C","atext":"孟子","src":"篇目→出处","note":"《许行》选自《孟子·滕文公上》。"},{"q":"《齐桓公伐楚》的作者是（　）","opts":["苏洵","柳宗元","孔子","左丘明"],"ans":"D","atext":"左丘明","src":"篇目→作者","note":"《齐桓公伐楚》：春秋，左丘明，选自《左传·僖公四年》。"},{"q":"庾信生活于（　）","opts":["西汉","春秋","战国末期","南北朝"],"ans":"D","atext":"南北朝","src":"人物→朝代","note":"庾信，南北朝。"},{"q":"《触龙说赵太后》的作者是（　）","opts":["刘向","汪琬","孟子","庄周"],"ans":"A","atext":"刘向","src":"篇目→作者","note":"《触龙说赵太后》：战国，刘向，选自《战国策·赵策四》。"},{"q":"韩非生活于（　）","opts":["西汉","战国","春秋","战国末期"],"ans":"B","atext":"战国","src":"人物→朝代","note":"韩非，战国。"},{"q":"梁晓声生活于（　）","opts":["当代","北魏","西汉","战国末期"],"ans":"A","atext":"当代","src":"人物→朝代","note":"梁晓声，当代。"},{"q":"杨万里生活于（　）","opts":["战国末期","南宋","战国","北宋"],"ans":"B","atext":"南宋","src":"人物→朝代","note":"杨万里，南宋。"},{"q":"毛泽东生活于（　）","opts":["北宋","春秋","秦代","战国末期"],"ans":"A","atext":"北宋","src":"人物→朝代","note":"毛泽东，北宋。"},{"q":"废名生活于（　）","opts":["秦代","现代","战国","战国末期"],"ans":"B","atext":"现代","src":"人物→朝代","note":"废名，现代。"},{"q":"伊索生活于（　）","opts":["战国末期","春秋","先秦","秦代"],"ans":"C","atext":"先秦","src":"人物→朝代","note":"伊索，先秦。"}],"p2":[{"q":"「凡七楹」中「楹」的意思是（　）","opts":["赠送，留给（读wèi）","胜过、超过","触碰，撞上，突过。","房屋一间为一楹"],"ans":"D","atext":"房屋一间为一楹","src":"实词释义","note":"《传是楼记》凡七楹　楹：柱子，引申为房屋一间。"},{"q":"「其身之可爱」中「可爱」的意思是（　）","opts":["平时、平素家居","通“阵”，列阵","值得爱惜","装进笼子，包笼"],"ans":"C","atext":"值得爱惜","src":"实词释义","note":"《留侯论》其身之可爱　可爱：值得珍爱，非今之喜爱义。"},{"q":"「焉用亡郑以陪邻」中「陪」的意思是（　）","opts":["远离。","冒死","增加","穿。"],"ans":"C","atext":"增加","src":"实词释义","note":"《烛之武退秦师》焉用亡郑以陪邻　陪邻：增加邻（晋）的土地。"},{"q":"「师进，次于陉」中「次」的意思是（　）","opts":["智谋和力量","临时驻扎","几乎、几乎多得","行走"],"ans":"B","atext":"临时驻扎","src":"实词释义","note":"《齐桓公伐楚》师进，次于陉　军队驻扎。"},{"q":"「而后乃今培风。」中「培」的意思是（　）","opts":["送物给人、赠送（音jī）","恼怒、怨恨（音yùn）","通\"凭\"，凭借、乘。","疏散、流通（音xiè）"],"ans":"C","atext":"通\"凭\"，凭借、乘。","src":"实词释义","note":"《逍遥游》而后乃今培风。　一说培为\"凭借\"；培风即凭风。"},{"q":"「张良出，要项伯」中「要」的意思是（　）","opts":["疲困、衰败","通\"已\"，停止。","通“邀”，邀请","如果真的"],"ans":"C","atext":"通“邀”，邀请","src":"实词释义","note":"《鸿门宴》张良出，要项伯　“要”读yāo，通“邀”。"},{"q":"「君子博学而日参省乎己」中「参」的意思是（　）","opts":["能施展才能就任职，不能就辞职","检验、检查（音cān）","放大火烧。","勉励，鼓励"],"ans":"B","atext":"检验、检查（音cān）","src":"实词释义","note":"《劝学》君子博学而日参省乎己　参省：检查反省。"},{"q":"「大都不过参国之一」中「参」的意思是（　）","opts":["偏爱","通“三”","推却、拒绝","竭力、极力"],"ans":"B","atext":"通“三”","src":"实词释义","note":"《郑伯克段于鄢》大都不过参国之一　参读sān，国都的三分之一。"},{"q":"「吾方以此为鉴」中「鉴」的意思是（　）","opts":["屯驻，退守","日光，此指太阳","鉴戒、教训","并力，合力"],"ans":"C","atext":"鉴戒、教训","src":"实词释义","note":"《传是楼记》吾方以此为鉴　鉴：引以为戒。"},{"q":"「然且裒聚未几」中「裒聚」的意思是（　）","opts":["通“三”","安抚","倾覆","聚集"],"ans":"D","atext":"聚集","src":"实词释义","note":"《传是楼记》然且裒聚未几　裒（póu）聚：聚敛。"}],"p3":[{"q":"由也为之，比及三年，可使有勇，且知方也。","a":"让我仲由去治理，等到三年，可使人人有勇气，而且懂得礼义。","note":"方：正道，指明辨是非的礼义。","src":"子路曾皙冉有公西华侍坐"},{"q":"兄闻，喜曰：“弟必大贵，此狐来避雷霆劫也。”","a":"哥哥听说后，高兴地说：“弟弟必定大贵，这是狐狸来躲避雷霆之劫啊。”","note":"点出小翠一家报恩的前缘。","src":"小翠"},{"q":"琬顾谓藏之之难不若守之之难，守之之难不若读之之难，尤不若躬体而心得之之难。","a":"我却认为藏书的难比不上守书的难，守书的难比不上读书的难，更比不上亲身实践而心有所得的难。","note":"层层递进的主旨句。顾：转折连词。","src":"传是楼记"},{"q":"是以肠一日而九回，居则忽忽若有所亡，出则不知其所往。","a":"因此痛苦之情在腹中一天九转，在家就恍恍惚惚若有所失，出门就不知要往哪里去。","note":"“肠一日九回”夸张写内心痛苦；两个并列句写精神恍惚。","src":"报任安书"},{"q":"草创未就，会遭此祸，惜其不成，是以就极刑而无愠色。","a":"草稿还没有完成，恰巧遇上这场大祸，我痛惜书没有写成，因此身受最重的刑罚也没有怨恨的神色。","note":"“就”接近、承受；“愠”怨恨。说明为著书而忍辱。","src":"报任安书"},{"q":"陈相见许行而大悦，尽弃其学而学焉。陈相见孟子，道许行之言曰：\"滕君，则诚贤君也；虽然，未闻道也。贤者与民并耕而食，饔飧而治。今也滕有仓廪府库，则是厉民而以自养也，恶得贤？\"","a":"陈相见到许行非常高兴，完全抛弃自己原来的学说而向他学习。陈相见到孟子，转述许行的话说：\"滕君确实是个贤明的君主；虽然如此，他还没有懂得真正的道理。贤人应该和百姓一起耕种来获取食物，自己做饭一边治理天下。如今滕国有粮仓府库，这是损害百姓来供养自己，怎么能算贤明呢？\"","note":"尽弃其学：完全抛弃自己原来的学说；饔飧而治：自己做饭而治理；厉民：损害百姓；恶得贤：怎么能算贤明。","src":"许行"},{"q":"其是之谓乎？","a":"大概说的就是这种情况吧？","note":"“是之谓”即“谓是”，宾语前置。","src":"郑伯克段于鄢"},{"q":"阙秦以利晋，唯君图之。","a":"损害秦国而使晋国得利，希望您考虑这件事。","note":"唯：表希望的语气副词。说辞落脚点。","src":"烛之武退秦师"},{"q":"因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。","a":"靠过别人的力量反而损害他，是不仁；失去同盟国，是不智；以混乱相攻代替步调一致，是不武。","note":"排比三句。知通智；所与：同盟者。","src":"烛之武退秦师"},{"q":"不义不暱，厚将崩。","a":"对君不义、对兄不亲，土地再厚大也会垮台。","note":"暱同昵，亲近；厚：势力雄厚；崩：崩溃。","src":"郑伯克段于鄢"},{"q":"今逐客以资敌国，损民以益雠，内自虚而外树怨于诸侯，求国无危，不可得也。","a":"如今驱逐客卿来资助敌国，减损百姓来增加仇敌，对内造成自己空虚，对外在诸侯中树立怨恨，想求得国家没有危险，是不可能的啊。","note":"“雠”通“仇”；“树怨于诸侯”状语后置。总结全文，指出逐客必致危亡。","src":"谏逐客书"},{"q":"故不登高山，不知天之高也；不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。干、越、夷、貉之子，生而同声，长而异俗，教使之然也。《诗》曰：“嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。”神莫大于化道，福莫长于无祸。","a":"所以不登高山，就不知道天有多高；不面临深溪，就不知道地有多厚；不听取先王的遗训，就不知道学问的博大。干国、越国、夷族、貉族的孩子，初生时哭声相同，长大后习俗各异，是教化使他们这样的。《诗经》说：\"唉，你们君子，不要常贪图安逸休息。谨慎地安守你的职位，爱好正直的品德。神灵听到这些，会赐给你大福。\"精神的修养没有比受道的熏陶感化更大的，福分没有比无灾无祸更长久的。","note":"临：俯视；遗言：遗训；干越夷貉：各族名；靖共：通「靖恭」，谨慎恭敬；介：赐、大。","src":"劝学"},{"q":"昭王之不复，君其问诸水滨。","a":"昭王没有回去，您还是去问水边的人吧。","note":"诸=之于。婉言拒绝承担昭王溺死之责。","src":"齐桓公伐楚"},{"q":"城北徐公，齐国之美丽者也。","a":"城北的徐公，是齐国的美男子。","note":"“……者也”表判断句。","src":"邹忌讽齐王纳谏"},{"q":"居则曰：“不吾知也！”如或知尔，则何以哉？","a":"（你们）平时常说：“不了解我啊！”如果有人了解你们，那打算怎么做呢？","note":"“不吾知”“何以”均为宾语前置，即“不知吾”“以何”。","src":"子路曾皙冉有公西华侍坐"},{"q":"六国破灭，非兵不利，战不善，弊在赂秦。","a":"六国灭亡，不是武器不锋利、仗打得不好，弊病在于贿赂秦国。","note":"开门见山提出中心论点；兵：兵器。判断句兼否定排比。","src":"六国论"},{"q":"丘也闻有国有家者，不患寡而患不均，不患贫而患不安。","a":"我听说诸侯和大夫，不担忧贫困而担忧分配不均，不担忧人少而担忧不安定。","note":"“也”句中语气词；孔子提出均贫富、安邦国的政治主张。","src":"季氏将伐颛臾"},{"q":"昆山徐健庵先生，筑楼于所居之后，凡七楹。","a":"昆山徐健庵先生，在他的住宅后面建造了一座楼，一共有七间。","note":"楹：房屋一间。开门见山交代楼的主人、位置、规模。","src":"传是楼记"},{"q":"人固有一死，或重于泰山，或轻于鸿毛，用之所趋异也。","a":"人本来就有一死，有的人死得比泰山还重，有的人死得比鸿毛还轻，这是因为他们所追求的东西不同啊。","note":"“于”介词表比较；“趋”趋向、目的。全句为生死价值观名句，判断句。","src":"报任安书"},{"q":"枕席而卧，则清泠之状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋。","a":"设枕铺席躺下，清凉明净的景色与眼睛相契合，回旋潺潺的水声与耳朵相契合，悠远虚空的境界与精神相契合，深沉幽静的气氛与心灵相契合。","note":"四“谋”字排比，由目、耳到神、心，层层深入；情景交融的名句。","src":"钴鉧潭西小丘记"}]},{"no":7,"date":"2026-11-04","date_end":"2026-11-05","pieces":["吕相绝秦","秋水","劝学","许行","烛之武退秦师","论贵粟疏"],"theme":"综合练习 7","p1":[{"q":"《鸿门宴》选自（　）","opts":["庄子","战国策","水经注","史记"],"ans":"D","atext":"史记","src":"篇目→出处","note":"《鸿门宴》选自《史记·项羽本纪》。"},{"q":"鲍照生活于（　）","opts":["西汉","春秋","南朝宋","秦代"],"ans":"C","atext":"南朝宋","src":"人物→朝代","note":"鲍照，南朝宋。"},{"q":"《巫山巫峡》选自（　）","opts":["柳河东集","嘉祐集","汉书","水经注"],"ans":"D","atext":"水经注","src":"篇目→出处","note":"《巫山巫峡》选自《水经注·江水》。"},{"q":"司马相如生活于（　）","opts":["秦代","战国末期","战国","汉代"],"ans":"D","atext":"汉代","src":"人物→朝代","note":"司马相如，汉代。"},{"q":"苏辙生活于（　）","opts":["北宋","战国","战国末期","春秋"],"ans":"A","atext":"北宋","src":"人物→朝代","note":"苏辙，北宋。"},{"q":"林语堂生活于（　）","opts":["北魏","战国末期","现代","西汉"],"ans":"C","atext":"现代","src":"人物→朝代","note":"林语堂，现代。"},{"q":"梁实秋生活于（　）","opts":["战国","现代","秦代","北魏"],"ans":"B","atext":"现代","src":"人物→朝代","note":"梁实秋，现代。"},{"q":"冯至生活于（　）","opts":["北魏","战国末期","秦代","现代"],"ans":"D","atext":"现代","src":"人物→朝代","note":"冯至，现代。"},{"q":"曹植生活于（　）","opts":["北宋","战国末期","战国","三国魏"],"ans":"D","atext":"三国魏","src":"人物→朝代","note":"曹植，三国魏。"},{"q":"尤袤生活于（　）","opts":["战国末期","南宋","秦代","西汉"],"ans":"B","atext":"南宋","src":"人物→朝代","note":"尤袤，南宋。"},{"q":"穆旦生活于（　）","opts":["秦代","现代","北宋","战国末期"],"ans":"B","atext":"现代","src":"人物→朝代","note":"穆旦，现代。"},{"q":"贾平凹生活于（　）","opts":["战国","秦代","当代","战国末期"],"ans":"C","atext":"当代","src":"人物→朝代","note":"贾平凹，当代。"},{"q":"左丘明生活于（　）","opts":["战国","春秋","秦代","北魏"],"ans":"B","atext":"春秋","src":"人物→朝代","note":"左丘明，春秋。"},{"q":"曹操生活于（　）","opts":["西汉","东汉末","秦代","北魏"],"ans":"B","atext":"东汉末","src":"人物→朝代","note":"曹操，东汉末。"},{"q":"《鸿门宴》的作者是（　）","opts":["柳宗元","司马迁","晁错","韩愈"],"ans":"B","atext":"司马迁","src":"篇目→作者","note":"《鸿门宴》：西汉，司马迁，选自《史记·项羽本纪》。"},{"q":"《郑伯克段于鄢》的作者是（　）","opts":["左丘明","孔子","韩愈","蒲松龄"],"ans":"A","atext":"左丘明","src":"篇目→作者","note":"《郑伯克段于鄢》：春秋，左丘明，选自《左传·隐公元年》。"},{"q":"《郑伯克段于鄢》选自（　）","opts":["汉书","水经注","韩昌黎集","左传"],"ans":"D","atext":"左传","src":"篇目→出处","note":"《郑伯克段于鄢》选自《左传·隐公元年》。"},{"q":"《谏逐客书》的作者是（　）","opts":["韩愈","汪琬","李斯","司马迁"],"ans":"C","atext":"李斯","src":"篇目→作者","note":"《谏逐客书》：秦代，李斯，选自《史记·李斯列传》（亦见《文选》）。"},{"q":"北岛生活于（　）","opts":["当代","战国末期","秦代","北魏"],"ans":"A","atext":"当代","src":"人物→朝代","note":"北岛，当代。"},{"q":"梁斌生活于（　）","opts":["战国","北宋","当代","西汉"],"ans":"C","atext":"当代","src":"人物→朝代","note":"梁斌，当代。"}],"p2":[{"q":"「又往往厚金帛以易之」中「易」的意思是（　）","opts":["交换、购置","智谋和力量","托辞、借口","名词作状语，每天"],"ans":"A","atext":"交换、购置","src":"实词释义","note":"《传是楼记》又往往厚金帛以易之　易：买、换取。"},{"q":"「贾人夏则资皮」中「资」的意思是（　）","opts":["积蓄，准备","官印（篆文代指）","任凭、听凭","通“稀”，稀疏"],"ans":"A","atext":"积蓄，准备","src":"实词释义","note":"《勾践灭吴》贾人夏则资皮　囤积以备乏。"},{"q":"「役婢仆，厌膏粱」中「厌」的意思是（　）","opts":["凭借、借助","安抚，安定。","满。","饱、满足"],"ans":"D","atext":"饱、满足","src":"实词释义","note":"《小翠》役婢仆，厌膏粱　厌通“餍”，饱食。"},{"q":"「治官府」中「治」的意思是（　）","opts":["“之于”的合音","才能，指为政之所陈述的志向","同进同退，步调一致","修理、整治（此指修缮官府）"],"ans":"D","atext":"修理、整治（此指修缮官府）","src":"实词释义","note":"《论贵粟疏》治官府　修理官府房舍，出徭役之一。"},{"q":"「老臣贱息舒祺」中「贱息」的意思是（　）","opts":["高险如屏障的山峰","通\"已\"，停止。","对自己儿子的谦称","通“抵”，大抵、大都"],"ans":"C","atext":"对自己儿子的谦称","src":"实词释义","note":"《触龙说赵太后》老臣贱息舒祺　息：子；贱息犹言“犬子”。"},{"q":"「我决起而飞，抢榆枋而止。」中「抢」的意思是（　）","opts":["通“仇”，仇敌","出言屈服、投降","计算、数着","触碰，撞上，突过。"],"ans":"D","atext":"触碰，撞上，突过。","src":"实词释义","note":"《逍遥游》我决起而飞，抢榆枋而止。　抢(qiāng)：触、撞，指飞上树梢。"},{"q":"「而陛下说之」中「说」的意思是（　）","opts":["名词作动词，使眼色","通“悦”，喜悦、喜爱","相称、相配","名词作动词，从事农业生产"],"ans":"B","atext":"通“悦”，喜悦、喜爱","src":"实词释义","note":"《谏逐客书》而陛下说之　“说”读yuè，通“悦”。"},{"q":"「寻山口西北道二百步」中「道」的意思是（　）","opts":["行走","没有","挖隧道","空闲。"],"ans":"A","atext":"行走","src":"实词释义","note":"《钴鉧潭西小丘记》寻山口西北道二百步　“道”本为道路，此活用为“走、行走”。"},{"q":"「楚人恶君之二三其德也」中「二三」的意思是（　）","opts":["通“价”，价格","反复无常，不专一","民，外来的移民。","投，落下，跌落。"],"ans":"B","atext":"反复无常，不专一","src":"实词释义","note":"《吕相绝秦》楚人恶君之二三其德也　数词用作动词，使……时二时三。"},{"q":"「余怜而售之」中「售」的意思是（　）","opts":["通“熟”，仔细","坚持正义","凭借、借助","卖出；又指买入"],"ans":"D","atext":"卖出；又指买入","src":"实词释义","note":"《钴鉧潭西小丘记》余怜而售之　“售”此为“买下来”，与上文“不售（卖不出）”同词反训。"}],"p3":[{"q":"文公恐惧，绥静诸侯，秦师克还无害，则是我有大造于西也。","a":"文公为之恐惧，安抚诸侯，秦军才得以全身而退，这么说我们对西方（秦）有大功。","note":"绥静：安抚；大造：大恩惠。","src":"吕相绝秦"},{"q":"而吾未尝以此自多者，自以比形于天地，而受气于阴阳。","a":"可是我从不因此自我夸耀，因为我自以为从天地禀受了形体。","note":"多：意动，夸耀；比形：寄形、禀形。写海若不自满。","src":"秋水"},{"q":"康公，我之自出。","a":"康公，是我们晋国的外甥（晋女所生）。","note":"判断句。康公母为晋穆姬，故云“我之自出”。","src":"吕相绝秦"},{"q":"蔑死我君，寡我襄公，迭我殽地。","a":"蔑视我们故去的国君，欺侮我们襄公，侵犯我们的殽地。","note":"寡：意动，欺藐；迭：通“轶”，侵犯。","src":"吕相绝秦"},{"q":"是故质的张而弓矢至焉，林木茂而斧斤至焉，树成荫而众鸟息焉，醯酸而蚋聚焉。","a":"所以靶子一摆开，弓箭就射来了；树林一茂盛，斧头就来了；树荫一成片，鸟就栖息了；醋一变酸，蚊蚋就聚拢来了。","note":"“质的”箭靶（的dì）；“焉”兼词。四句博喻，说明物各从其类、言行动则招应。","src":"劝学"},{"q":"然则治天下独可耕且为与？","a":"那么唯独治理天下就能一边种地一边兼做吗？","note":"反问，归谬法。由\"百工不可耕且为\"推出治天下亦有分工。","src":"许行"},{"q":"贤者与民并耕而食，饔飧而治。","a":"贤君应当和百姓一起种地吃饭，一面做饭一面治理国事。","note":"饔飧：自炊。这是农家\"君民并耕\"的主张，孟子反驳的靶子。","src":"许行"},{"q":"当尧之时，天下犹未平，洪水横流，泛滥于天下。草木畅茂，禽兽繁殖，五谷不登，禽兽偪人。兽蹄鸟迹之道，交于中国。尧独忧之，举舜而敷治焉。舜使益掌火，益烈山泽而焚之，禽兽逃匿。禹疏九河，瀹济漯，而注诸海；决汝汉，排淮泗，而注之江，然后中国可得而食也。当是时也，禹八年于外，三过其门而不入，虽欲耕，得乎？","a":"在尧的时候，天下还没有平定，洪水四处横流，泛滥于天下。草木茂盛，禽兽繁殖，五谷不收，禽兽侵害人类。野兽的蹄印和鸟的踪迹，纵横交错于中原。尧独自为此忧虑，举用舜来治理。舜派伯益掌管火政，伯益在山泽中燃起大火焚烧，禽兽逃跑躲藏。禹疏通九河，疏导济水、漯水，使它们流入大海；开凿汝水、汉水，排除淮水、泗水，使它们流入长江，然后中原才能种植收获。在这个时候，禹在外八年，三次经过自己的家门都没有进去，虽然他想耕种，能行吗？","note":"平：安定；登：成熟、收成；偪：通「逼」，侵害；敷治：治理；瀹：疏导；决：开凿；排：排除。","src":"许行"},{"q":"佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”公从之。辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”公曰：“吾不能早用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉。”许之。","a":"佚之狐对郑文公说：\"国家危险了，如果派烛之武去见秦国国君，军队一定会撤退。\"郑文公听从了。烛之武推辞说：\"我壮年的时候，尚且不如别人；如今老了，不能做什么了。\"郑文公说：\"我不能早早重用您，如今情况紧急才来求您，这是我的过错。然而郑国灭亡了，对您也有不利啊。\"烛之武答应了。","note":"辞：推辞；壮：壮年；无能为也已：不能做什么了，「已」通「矣」。","src":"烛之武退秦师"},{"q":"有者半贾而卖，无者取倍称之息，于是有卖田宅、鬻子孙以偿债者矣。","a":"有粮的人半价出卖，没粮的人借加倍利息的高利贷，于是就有了卖掉田宅、卖掉子孙来还债的人。","note":"“贾”通“价”；“倍称之息”加倍利息；“鬻”卖。写农民破产。","src":"论贵粟疏"},{"q":"穆、襄即世，康、灵即位。康公，我之自出，又欲阙翦我公室，倾覆我社稷，帅我蝥贼，以来荡摇我边疆。我是以有令狐之役。康犹不悛，入我河曲，伐我涑川，俘我王官，翦我羁马。我是以有河曲之战。东道之不通，则是康公绝我好也。","a":"穆公、襄公去世，康公、灵公即位。康公是我晋国女子所生，却又想铲除我公室，颠覆我国家，带领我晋国的内奸，来扰乱我边疆，因此我们才打了令狐之战。康公仍然不改，侵入我河曲，攻打我涑川，掳掠我王官，剪除我羁马，因此我们才打了河曲之战。东方道路不通，就是康公断绝了我们之间的友好。","note":"即世：去世；我之自出：我国女子所生；阙翦：铲除；蝥贼：内奸；悛：悔改；俘：掳掠。","src":"吕相绝秦"},{"q":"此其比万物也，不似毫末之在于马体乎？","a":"人和万物相比，不就像一根毫毛在马身上吗？","note":"毫末：毫毛尖端。极言人之渺小。","src":"秋水"},{"q":"故君子居必择乡，游必就士，所以防邪辟而近中正也。","a":"所以君子居住一定要选择乡里，交游一定要接近贤士，这是用来防止邪恶而接近正道的。","note":"“所以”：用来……的（方法）。由环境之喻得出重择乡交友的结论。","src":"劝学"},{"q":"此非所以跨海内、制诸侯之术也。","a":"这不是用来统一天下、制服诸侯的方法啊。","note":"“所以”：用来……的方法；判断句（否定判断）。紧切秦王兼并天下之心。","src":"谏逐客书"},{"q":"千金之子，不死于盗贼，何者？其身之可爱，而盗贼之不足以死也。","a":"富贵人家的子弟，不死在盗贼手里，为什么呢？因为他的生命值得爱惜，不值得为盗贼而死。","note":"可爱：值得爱惜（古今异义）。设喻说明张良不应行刺冒险。","src":"留侯论"},{"q":"齐侯与蔡姬乘舟于囿，荡公。公惧变色；禁之，不可。公怒，归之，未之绝也。蔡人嫁之。","a":"齐桓公和蔡姬在园囿中乘船，蔡姬摇晃船身戏弄桓公。桓公害怕，脸色都变了；制止她，她不停。桓公发怒，把她送回蔡国，但还没有断绝婚姻关系。蔡国人却把她改嫁了。","note":"荡：摇晃；归之：把她送回娘家；「未之绝」宾语前置，即「未绝之」。","src":"齐桓公伐楚"},{"q":"南方有鸟焉，名曰蒙鸠，以羽为巢，而编之以发，系之苇苕，风至苕折，卵破子死。巢非不完也，所系者然也。","a":"南方有一种鸟，名叫蒙鸠，用羽毛做巢，用毛发编织起来，系在芦苇的嫩条上，风一吹芦苇条折断，鸟蛋摔破，雏鸟死掉。巢不是不完善，是系的地方使它这样的。","note":"编之以发：状语后置，即「以发编之」；苕：芦苇嫩条；所系者然：系的地方使它这样。","src":"劝学"},{"q":"位尊而无功，奉厚而无劳，而挟重器多也。","a":"地位尊贵却没有功勋，俸禄丰厚却没有劳绩，拥有的珍宝太重了。","note":"奉通“俸”；三个并列分句，排比重申“无功不能受尊”之理。","src":"触龙说赵太后"},{"q":"一座大惊，皆感激为云泣下。","a":"满座的人大为震惊，都被感动得为南霁云流下眼泪。","note":"感激：感动奋发（古今异义）。写断指之事的震撼力。","src":"张中丞传后叙"},{"q":"老吾老，以及人之老；幼吾幼，以及人之幼：天下可运于掌。","a":"敬爱自己的老人，推广到敬爱别人的老人；爱护自己的孩子，推广到爱护别人的孩子：统一天下就像在手掌上转动东西一样容易。","note":"老、幼均形作动/形作名；及：推及。\"推恩\"的核心。","src":"齐桓晋文之事"}]},{"no":8,"date":"2026-11-05","date_end":"2026-11-06","pieces":["巫山巫峡","秋水","逍遥游","触龙说赵太后","传是楼记","郑伯克段于鄢"],"theme":"综合练习 8","p1":[{"q":"《论贵粟疏》的作者是（　）","opts":["李斯","司马迁","晁错","汪琬"],"ans":"C","atext":"晁错","src":"篇目→作者","note":"《论贵粟疏》：西汉，晁错，选自《汉书·食货志》。"},{"q":"《劝学》选自（　）","opts":["史记","左传","水经注","荀子"],"ans":"D","atext":"荀子","src":"篇目→出处","note":"《劝学》选自《荀子·劝学》（节选）。"},{"q":"扬雄生活于（　）","opts":["战国末期","春秋","西汉","北宋"],"ans":"C","atext":"西汉","src":"人物→朝代","note":"扬雄，西汉。"},{"q":"「此情可待成追忆，只是当时已惘然。」出自（　）","opts":["蝶恋花","锦瑟","石灰吟","红楼梦"],"ans":"B","atext":"锦瑟","src":"名句→出处","note":"“此情可待成追忆，只是当时已惘然。”——李商隐《锦瑟》。"},{"q":"「先天下之忧而忧，后天下之乐而乐。」出自（　）","opts":["赤壁赋","送元二使安西","将进酒","岳阳楼记"],"ans":"D","atext":"岳阳楼记","src":"名句→出处","note":"\"先天下之忧而忧，后天下之乐而乐。\"——出自范仲淹《岳阳楼记》，表现政治抱负。"},{"q":"「多情自古伤离别，更那堪冷落清秋节。」出自（　）","opts":["雨霖铃","念奴娇","己亥杂诗","使至塞上"],"ans":"A","atext":"雨霖铃","src":"名句→出处","note":"“多情自古伤离别，更那堪冷落清秋节。”——柳永《雨霖铃》。"},{"q":"「富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。」出自（　）","opts":["泊船瓜洲","孟子","雨霖铃","游山西村"],"ans":"B","atext":"孟子","src":"名句→出处","note":"“富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。”——《孟子·滕文公下》。"},{"q":"「春蚕到死丝方尽，蜡炬成灰泪始干。」出自（　）","opts":["登飞来峰","声声慢","石灰吟","无题"],"ans":"D","atext":"无题","src":"名句→出处","note":"“春蚕到死丝方尽，蜡炬成灰泪始干。”——李商隐《无题》。"},{"q":"「得道者多助，失道者寡助。」出自（　）","opts":["水调歌头","过零丁洋","孟子","滕王阁序"],"ans":"C","atext":"孟子","src":"名句→出处","note":"“得道者多助，失道者寡助。”——《孟子·公孙丑下》。"},{"q":"「同是天涯沦落人，相逢何必曾相识。」出自（　）","opts":["泊秦淮","琵琶行","归园田居","菩萨蛮"],"ans":"B","atext":"琵琶行","src":"名句→出处","note":"“同是天涯沦落人，相逢何必曾相识。”——白居易《琵琶行》。"},{"q":"「问渠那得清如许？为有源头活水来。」出自（　）","opts":["观书有感","南乡子","梦游天姥吟留别","进学解"],"ans":"A","atext":"观书有感","src":"名句→出处","note":"“问渠那得清如许？为有源头活水来。”——朱熹《观书有感》。"},{"q":"「兴，百姓苦；亡，百姓苦。」出自（　）","opts":["红楼梦","题西林壁","游山西村","山坡羊"],"ans":"D","atext":"山坡羊","src":"名句→出处","note":"“兴，百姓苦；亡，百姓苦。”——张养浩《山坡羊·潼关怀古》。"},{"q":"「吾生也有涯，而知也无涯。」出自（　）","opts":["庄子","琵琶行","醉翁亭记","泊秦淮"],"ans":"A","atext":"庄子","src":"名句→出处","note":"“吾生也有涯，而知也无涯。”——《庄子·养生主》。"},{"q":"「桃李不言，下自成蹊。」出自（　）","opts":["诗经","史记","题西林壁","念奴娇"],"ans":"B","atext":"史记","src":"名句→出处","note":"\"桃李不言，下自成蹊。\"——出自《史记·李将军列传》，喻品德高尚自然受人敬仰。"},{"q":"「欲穷千里目，更上一层楼。」出自（　）","opts":["行路难","山坡羊","登鹳雀楼","赤壁赋"],"ans":"C","atext":"登鹳雀楼","src":"名句→出处","note":"“欲穷千里目，更上一层楼。”——王之涣《登鹳雀楼》。"},{"q":"「回眸一笑百媚生，六宫粉黛无颜色。」出自（　）","opts":["长恨歌","示儿","进学解","六国论"],"ans":"A","atext":"长恨歌","src":"名句→出处","note":"“回眸一笑百媚生，六宫粉黛无颜色。”——白居易《长恨歌》。"},{"q":"「生当作人杰，死亦为鬼雄。」出自（　）","opts":["报任安书","夏日绝句","行路难","望庐山瀑布"],"ans":"B","atext":"夏日绝句","src":"名句→出处","note":"“生当作人杰，死亦为鬼雄。”——李清照《夏日绝句》。"},{"q":"「满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？」出自（　）","opts":["离思","爱莲说","劝学","红楼梦"],"ans":"D","atext":"红楼梦","src":"名句→出处","note":"\"满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？\"——出自《红楼梦》开篇诗。"},{"q":"「长太息以掩涕兮，哀民生之多艰。」出自（　）","opts":["别董大","离骚","三国演义","劝学"],"ans":"B","atext":"离骚","src":"名句→出处","note":"“长太息以掩涕兮，哀民生之多艰。”——屈原《离骚》。"},{"q":"「寻寻觅觅，冷冷清清，凄凄惨惨戚戚。」出自（　）","opts":["饮酒","声声慢","泊船瓜洲","琵琶行"],"ans":"B","atext":"声声慢","src":"名句→出处","note":"“寻寻觅觅，冷冷清清，凄凄惨惨戚戚。”——李清照《声声慢》。"}],"p2":[{"q":"「保民而王，莫之能御也。」中「保」的意思是（　）","opts":["灾患、损耗","兵器、武器","安抚，安定。","高险如屏障的山峰"],"ans":"C","atext":"安抚，安定。","src":"实词释义","note":"《齐桓晋文之事》保民而王，莫之能御也。　保民：使人民安定。"},{"q":"「而特出于荆轲、聂政之计」中「特」的意思是（　）","opts":["阻止、遏制","勉励，鼓励","只、仅仅","通“汝”，你"],"ans":"C","atext":"只、仅仅","src":"实词释义","note":"《留侯论》而特出于荆轲、聂政之计　特：只不过。"},{"q":"「请勾践女女于王」中「女女」的意思是（　）","opts":["诸侯自称的谦辞，不善","前“女”名词（女儿），后“女”动词（嫁女）","统治、治理（古代把治民比牧畜）","疏散、流通（音xiè）"],"ans":"B","atext":"前“女”名词（女儿），后“女”动词（嫁女）","src":"实词释义","note":"《勾践灭吴》请勾践女女于王　名词用作动词，嫁女儿。"},{"q":"「可以笼而有之」中「笼」的意思是（　）","opts":["通\"悦\"，高兴。","装进笼子，包笼","通\"辨\"，分别，区别。","点燃大火"],"ans":"B","atext":"装进笼子，包笼","src":"实词释义","note":"《钴鉧潭西小丘记》可以笼而有之　名词作状语，用笼子装。"},{"q":"「许子冠乎？」中「冠」的意思是（　）","opts":["该不会、莫不是","用杖打","戴帽子。","装进笼子，包笼"],"ans":"C","atext":"戴帽子。","src":"实词释义","note":"《许行》许子冠乎？　冠(guàn)：名作动，戴冠。"},{"q":"「夫晋何厌之有」中「厌」的意思是（　）","opts":["一夫所居之宅，住处。","通“隙”，隔阂、嫌怨","凭借、借助","通“餍”，满足"],"ans":"D","atext":"通“餍”，满足","src":"实词释义","note":"《烛之武退秦师》夫晋何厌之有　宾语前置“有何厌”。"},{"q":"「时则不至，而控于地而已矣。」中「控」的意思是（　）","opts":["投，落下，跌落。","乡曲之士，见识浅陋的人。","损害，剥削。","预料，料想"],"ans":"A","atext":"投，落下，跌落。","src":"实词释义","note":"《逍遥游》时则不至，而控于地而已矣。　控：投、落。"},{"q":"「其平居无罪夷灭者」中「平居」的意思是（　）","opts":["辞让、拒绝","通\"斑\"，头发花白。","平时、平素家居","通“隙”，隔阂、嫌怨"],"ans":"C","atext":"平时、平素家居","src":"实词释义","note":"《留侯论》其平居无罪夷灭者　平居：平日安居。"},{"q":"「不虞君之涉吾地也」中「虞」的意思是（　）","opts":["主持，管理","谦称自己死亡","预料，料想","鉴戒、教训"],"ans":"C","atext":"预料，料想","src":"实词释义","note":"《齐桓公伐楚》不虞君之涉吾地也　不虞：没料到。"},{"q":"「强留之，具食与乐」中「具」的意思是（　）","opts":["做贵族的仆役","备办、摆设","肃杀、凄清","接近、靠近、趋向"],"ans":"B","atext":"备办、摆设","src":"实词释义","note":"《张中丞传后叙》强留之，具食与乐　指贺兰进明备办酒食乐舞。"}],"p3":[{"q":"当崩之日，水逆流百余里，涌起数十丈。","a":"就在山崖崩塌那天，江水逆流而上一百多里，激起的波浪高达几十丈。","note":"写新崩滩由山崩成滩，侧笔见水势之险。","src":"巫山巫峡"},{"q":"秋水时至，百川灌河。","a":"秋天的洪水按季节到来，千百条河流注入黄河。","note":"时：按季节（名词作状语）；灌：注入。开篇写河伯初见壮阔而自喜。","src":"秋水"},{"q":"之二虫又何知！","a":"这两只小动物又懂得什么呢！","note":"之：此；何知：宾语前置（知何）。二虫指蜩与学鸠。","src":"逍遥游"},{"q":"老臣今者殊不欲食，乃自强步，日三四里，少益耆食，和于身。","a":"我近来很不想吃东西，就自己勉强走走，每天三四里，渐渐稍微想吃点东西，身体舒适些了。","note":"耆通“嗜”；“日三四里”“日”名词作状语；触龙以养生话题缓解太后情绪。","src":"触龙说赵太后"},{"q":"善读书者根柢于性命而究极于事功：沿流以溯源，无不探也；明体以适用，无不达也。","a":"善于读书的人以性命义理为根基，而最终落实于事功：顺着流来追溯源，没有探究不到的；明了本体而加以应用，没有不通达的。","note":"根柢、究极：名作动。体用结合的读书观。","src":"传是楼记"},{"q":"书曰：“郑伯克段于鄢。”段不弟，故不言弟；如二君，故曰克；称郑伯，讥失教也；谓之郑志。不言出奔，难之也。","a":"《春秋》记载说：\"郑伯在鄢地战胜了段。\"段不守做弟弟的本分，所以不说\"弟\"；如同两个国君相战，所以用\"克\"；称\"郑伯\"，是讥讽他失去对弟弟的教诲；说这是郑伯的本意。不写\"出奔\"，是为难以下笔（含有责难郑伯之意）。","note":"弟：通「悌」，守弟弟本分；克：战胜；志：本意；难之：对此为难，含责难意。","src":"郑伯克段于鄢"},{"q":"君子生非异也，善假于物也。","a":"君子的天性同一般人并没什么差别，只是善于借助外物罢了。","note":"判断句；“生”通“性”，天性；“假”借助。点明学习本质在于善假外物。","src":"劝学"},{"q":"积土成山，风雨兴焉；积水成渊，蛟龙生焉；积善成德，而神明自得，圣心备焉。故不积跬步，无以至千里；不积小流，无以成江海。骐骥一跃，不能十步；驽马十驾，功在不舍。锲而舍之，朽木不折；锲而不舍，金石可镂。蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。蟹六跪而二螯，非蛇鳝之穴无可寄托者，用心躁也。","a":"堆土成山，风雨就从那里兴起；积水成渊，蛟龙就在那里生长；积累善行养成品德，那么精神智慧自然获得，圣人的心境就具备了。所以不一步步积累，就无法到达千里之外；不汇集细小水流，就无法形成江海。骏马一跃，不能超过十步；劣马走十天也能达到，成功在于不停止。用刀刻一下就放下，即使是朽木也不能折断；不停地刻，金石也能雕刻成功。蚯蚓没有锋利的爪牙、强健的筋骨，却能上吃泥土，下饮地下水，是用心专一的缘故。螃蟹有六条腿和两只钳子，如果没有蛇和鳝鱼的洞穴就无处安身，是用心浮躁的缘故。","note":"兴焉：从这里兴起，「焉」兼词；跬步：半步；驽马十驾：劣马拉车走十天；锲：刻；镂：雕刻；六跪二螯：六条腿两只钳；躁：浮躁。","src":"劝学"},{"q":"夫子房受书于圯上之老人也，其事甚怪；然亦安知其非秦之世，有隐君子者出而试之。观其所以微见其意者，皆圣贤相与警戒之义；而世不察，以为鬼物，亦已过矣。且其意不在书。","a":"张良从圯上老人那里接受兵书，这件事很怪异；但也怎么知道不是秦朝时有一位隐居的君子出来考验他呢。看他用来稍稍显露心意的方式，都是圣贤相互警戒的道理；而世人不加审察，认为是鬼怪，也太过分了。况且老人的用意并不在兵书上。","note":"圯：桥；微见其意：稍稍显露心意；鬼物：鬼怪；过：过分。判断句「……也」。","src":"留侯论"},{"q":"赵太后新用事，秦急攻之。赵氏求救于齐，齐曰：“必以长安君为质，兵乃出。”太后不肯，大臣强谏。太后明谓左右：“有复言令长安君为质者，老妇必唾其面。”","a":"赵太后刚刚执政，秦国就加紧进攻赵国。赵国向齐国求救，齐国说：\"一定要用长安君作为人质，才出兵。\"赵太后不肯答应，大臣们极力劝谏。太后明确地告诉左右的人说：\"有再说让长安君去做人质的，我一定朝他脸上吐唾沫。\"","note":"用事：执政；质：人质；强谏：极力劝谏；唾其面：吐他一脸唾沫。","src":"触龙说赵太后"},{"q":"危而不持，颠而不扶，则将焉用彼相矣？","a":"（盲人）站不稳却不扶持，跌倒了却不搀扶，那还用那个辅助者干什么？","note":"以搀扶瞎子喻辅佐之责；焉：何必。","src":"季氏将伐颛臾"},{"q":"然亦安知其非秦之世，有隐君子者出而试之。","a":"然而又怎么知道那不是秦朝末年有一位隐居的高士，出来考验张良呢？","note":"安：怎么。翻案圯上老人授书的神怪之说。","src":"留侯论"},{"q":"然后卑事夫差，宦士三百人于吴，其身亲为夫差前马。","a":"然后谦卑地侍奉夫差，派三百人到吴国做奴仆，勾践亲自做夫差的马前卒。","note":"写勾践忍辱负重。前马：前驱。","src":"勾践灭吴"},{"q":"勾践之困于会稽，而归臣妾于吴者，三年而不倦。","a":"越王勾践被围困在会稽，而归顺吴国做奴仆，三年都不懈怠。","note":"归臣妾于吴：做奴仆。被动/状语后置。举勾践能忍为证。","src":"留侯论"},{"q":"鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。","a":"鹏迁往南海时，翅膀拍击水面三千里，乘着旋风盘旋而上九万里，凭借六月的大风离去。","note":"击：拍打；抟：盘旋；扶摇：旋风；六月息：六月海风。\"去以六月息\"为状语后置（以六月息去）。","src":"逍遥游"},{"q":"吾恐季孙之忧，不在颛臾，而在萧墙之内也。","a":"我恐怕季孙的忧虑不在颛臾，而在鲁国宫门之内啊。","note":"判断性结尾；“萧墙之内”暗指鲁君，成语“祸起萧墙”出处。","src":"季氏将伐颛臾"},{"q":"陈良之徒陈相与其弟辛，负耒耜而自宋之滕，曰：\"闻君行圣人之政，是亦圣人也，愿为圣人氓。\"","a":"陈良的门徒陈相和他的弟弟陈辛，背着农具从宋国来到滕国，说：\"听说您施行圣人的政治，您也是圣人了，愿意做圣人的百姓。\"","note":"负耒耜：背着农具；之：往、到；氓：百姓。","src":"许行"},{"q":"四方之士来者，必庙礼之。","a":"四方来投的贤士，一定在庙堂上招待他们。","note":"庙：名词作状语，在庙堂上。","src":"勾践灭吴"},{"q":"甚矣，书之多厄也！","a":"书籍遭遇的灾患太多了啊！","note":"主谓倒装（甚矣前置）。感叹藏书之难。","src":"传是楼记"},{"q":"安见方六七十如五六十而非邦也者？","a":"怎么见得纵横六七十里或五六十里的地方就不是国家呢？","note":"安：怎么、哪里；反问句，肯定冉有所治亦是邦国。","src":"子路曾皙冉有公西华侍坐"}]},{"no":9,"date":"2026-11-06","date_end":"2026-11-07","pieces":["子路曾皙冉有公西华侍坐","许行","张中丞传后叙","秋水","齐桓公伐楚","谏逐客书"],"theme":"综合练习 9","p1":[{"q":"「锲而不舍，金石可镂。」出自（　）","opts":["爱莲说","荀子","雨霖铃","山居秋暝"],"ans":"B","atext":"荀子","src":"名句→出处","note":"\"锲而不舍，金石可镂。\"——出自《荀子·劝学》，喻坚持不懈。"},{"q":"「身无彩凤双飞翼，心有灵犀一点通。」出自（　）","opts":["无题","三国演义","山坡羊","菩萨蛮"],"ans":"A","atext":"无题","src":"名句→出处","note":"“身无彩凤双飞翼，心有灵犀一点通。”——李商隐《无题》。"},{"q":"「东风不与周郎便，铜雀春深锁二乔。」出自（　）","opts":["诗经","赤壁","浣溪沙","锦瑟"],"ans":"B","atext":"赤壁","src":"名句→出处","note":"“东风不与周郎便，铜雀春深锁二乔。”——杜牧《赤壁》。"},{"q":"「忽如一夜春风来，千树万树梨花开。」出自（　）","opts":["白雪歌送武判官归京","送杜少府之任蜀州","自京赴奉先县咏怀五百字","酬乐天扬州初逢席上见赠"],"ans":"A","atext":"白雪歌送武判官归京","src":"名句→出处","note":"“忽如一夜春风来，千树万树梨花开。”——岑参《白雪歌送武判官归京》。"},{"q":"「不识庐山真面目，只缘身在此山中。」出自（　）","opts":["题西林壁","泊秦淮","登高","五代史伶官传序"],"ans":"A","atext":"题西林壁","src":"名句→出处","note":"“不识庐山真面目，只缘身在此山中。”——苏轼《题西林壁》。"},{"q":"「学而时习之，不亦说乎？有朋自远方来，不亦乐乎？」出自（　）","opts":["归园田居","蝶恋花","论语","赤壁赋"],"ans":"C","atext":"论语","src":"名句→出处","note":"“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？”——《论语·学而》。"},{"q":"「落霞与孤鹜齐飞，秋水共长天一色。」出自（　）","opts":["六国论","梦游天姥吟留别","滕王阁序","泊秦淮"],"ans":"C","atext":"滕王阁序","src":"名句→出处","note":"“落霞与孤鹜齐飞，秋水共长天一色。”——王勃《滕王阁序》。"},{"q":"「己所不欲，勿施于人。」出自（　）","opts":["论语","诗经","观书有感","天净沙"],"ans":"A","atext":"论语","src":"名句→出处","note":"“己所不欲，勿施于人。”——《论语·卫灵公》。"},{"q":"「安能摧眉折腰事权贵，使我不得开心颜。」出自（　）","opts":["梦游天姥吟留别","芙蓉楼送辛渐","冬夜读书示子聿","晓出净慈寺送林子方"],"ans":"A","atext":"梦游天姥吟留别","src":"名句→出处","note":"“安能摧眉折腰事权贵，使我不得开心颜。”——李白《梦游天姥吟留别》。"},{"q":"「天生我材必有用，千金散尽还复来。」出自（　）","opts":["水调歌头","归园田居","将进酒","泊船瓜洲"],"ans":"C","atext":"将进酒","src":"名句→出处","note":"“天生我材必有用，千金散尽还复来。”——李白《将进酒》。"},{"q":"「但愿人长久，千里共婵娟。」出自（　）","opts":["水调歌头","观书有感","游山西村","寄扬州韩绰判官"],"ans":"A","atext":"水调歌头","src":"名句→出处","note":"\"但愿人长久，千里共婵娟。\"——出自苏轼《水调歌头·明月几时有》，寄托对亲人的美好祝愿。"},{"q":"「采菊东篱下，悠然见南山。」出自（　）","opts":["饮酒","龟虽寿","青玉案","琵琶行"],"ans":"A","atext":"饮酒","src":"名句→出处","note":"“采菊东篱下，悠然见南山。”——陶渊明《饮酒》。"},{"q":"「长风破浪会有时，直挂云帆济沧海。」出自（　）","opts":["老子","劝学","报任安书","行路难"],"ans":"D","atext":"行路难","src":"名句→出处","note":"“长风破浪会有时，直挂云帆济沧海。”——李白《行路难》。"},{"q":"「尺有所短，寸有所长。」出自（　）","opts":["己亥杂诗","卜居","南乡子","后赤壁赋"],"ans":"B","atext":"卜居","src":"名句→出处","note":"“尺有所短，寸有所长。”——屈原《卜居》。"},{"q":"「不畏浮云遮望眼，自缘身在最高层。」出自（　）","opts":["龟虽寿","登飞来峰","诗经","无题"],"ans":"B","atext":"登飞来峰","src":"名句→出处","note":"“不畏浮云遮望眼，自缘身在最高层。”——王安石《登飞来峰》。"},{"q":"「沉舟侧畔千帆过，病树前头万木春。」出自（　）","opts":["自京赴奉先县咏怀五百字","送元二使安西","赋得古原草送别","酬乐天扬州初逢席上见赠"],"ans":"D","atext":"酬乐天扬州初逢席上见赠","src":"名句→出处","note":"“沉舟侧畔千帆过，病树前头万木春。”——刘禹锡《酬乐天扬州初逢席上见赠》。"},{"q":"「春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。」出自（　）","opts":["春晓","劝学","赤壁","醉翁亭记"],"ans":"A","atext":"春晓","src":"名句→出处","note":"\"春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。\"——出自孟浩然《春晓》。"},{"q":"「究天人之际，通古今之变，成一家之言。」出自（　）","opts":["虞美人","冬夜读书示子聿","报任安书","送元二使安西"],"ans":"C","atext":"报任安书","src":"名句→出处","note":"“究天人之际，通古今之变，成一家之言。”——司马迁《报任安书》。"},{"q":"「生于忧患，死于安乐。」出自（　）","opts":["孟子","赤壁","离思","报任安书"],"ans":"A","atext":"孟子","src":"名句→出处","note":"“生于忧患，死于安乐。”——《孟子·告子下》。"},{"q":"「不积跬步，无以至千里；不积小流，无以成江海。」出自（　）","opts":["登鹳雀楼","示儿","锦瑟","劝学"],"ans":"D","atext":"劝学","src":"名句→出处","note":"“不积跬步，无以至千里；不积小流，无以成江海。”——荀子《劝学》。"}],"p2":[{"q":"「怒而飞，其翼若垂天之云。」中「怒」的意思是（　）","opts":["脚后跟，引申为走到、亲自到。","奋发，这里指鼓起翅膀、用力鼓动。","安居于一地、附着于土地（著zhuó）","间或、偶然、断断续续"],"ans":"B","atext":"奋发，这里指鼓起翅膀、用力鼓动。","src":"实词释义","note":"《逍遥游》怒而飞，其翼若垂天之云。　\"怒\"在此非愤怒，形容振翅奋起的样子。"},{"q":"「抟扶摇羊角而上者九万里，绝云气，负青天。」中「绝」的意思是（　）","opts":["修理、整治（此指修缮官府）","推却、拒绝","通“智”，明智","直上穿过，超越。"],"ans":"D","atext":"直上穿过，超越。","src":"实词释义","note":"《逍遥游》抟扶摇羊角而上者九万里，绝云气，负青天。　绝：穿越、越过。"},{"q":"「可谓智力孤危」中「智力」的意思是（　）","opts":["智谋和力量","事务、要着","舍弃、剔除","穷尽、推究"],"ans":"A","atext":"智谋和力量","src":"实词释义","note":"《六国论》可谓智力孤危　今义为一个词。"},{"q":"「无庸，将自及」中「庸」的意思是（　）","opts":["通“供”，供给","偷看、观察","通“用”","说，谈论。"],"ans":"C","atext":"通“用”","src":"实词释义","note":"《郑伯克段于鄢》无庸，将自及　无庸即不必。"},{"q":"「虽乘奔御风，不以疾也」中「奔」的意思是（　）","opts":["飞奔的马","研究，奉行。","预先逃跑","横渡、横穿"],"ans":"A","atext":"飞奔的马","src":"实词释义","note":"《巫山巫峡》虽乘奔御风，不以疾也　“奔”本为奔跑，此指快跑的马。"},{"q":"「旦日不可不蚤自来谢项王」中「蚤」的意思是（　）","opts":["向东","通“早”","私下、谦指自己","战胜，攻克"],"ans":"B","atext":"通“早”","src":"实词释义","note":"《鸿门宴》旦日不可不蚤自来谢项王　“蚤”通“早”。"},{"q":"「今尔出于崖涘，观于大海，乃知尔丑。」中「丑」的意思是（　）","opts":["鄙陋，浅薄。","改，悔改","通“邀”，邀请","间或、偶然、断断续续"],"ans":"A","atext":"鄙陋，浅薄。","src":"实词释义","note":"《秋水》今尔出于崖涘，观于大海，乃知尔丑。　丑：此处指见识浅陋。"},{"q":"「曾不能疾走」中「曾」的意思是（　）","opts":["缠绕、被加在身","通“阵”，列阵","经过","竟、简直"],"ans":"D","atext":"竟、简直","src":"实词释义","note":"《触龙说赵太后》曾不能疾走　曾（zēng）：加强否定语气。"},{"q":"「当淮阴破齐而欲自王」中「王」的意思是（　）","opts":["用杖打","迎接","称王","你的父亲"],"ans":"C","atext":"称王","src":"实词释义","note":"《留侯论》当淮阴破齐而欲自王　王（wàng）：称王。"},{"q":"「观其所以微见其意者」中「见」的意思是（　）","opts":["量（长短）。","对自己儿子的谦称","兵器、武器","表现、显露"],"ans":"D","atext":"表现、显露","src":"实词释义","note":"《留侯论》观其所以微见其意者　见（xiàn）：表露。"}],"p3":[{"q":"非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。","a":"不敢说能做到，只是愿意学习。宗庙祭祀或诸侯会盟，我愿穿着礼服、戴着礼帽，做一个小小的赞礼人。","note":"端章甫：名词活用为动词；“小相”是公西华自谦之辞。","src":"子路曾皙冉有公西华侍坐"},{"q":"今也滕有仓廪府库，则是厉民而以自养也，恶得贤？","a":"如今滕国有储粮的仓廪、存财的府库，这是损害百姓来供养自己，怎么算贤明呢？","note":"厉：损害；恶(wū)：怎么。陈相转述许行的责难。","src":"许行"},{"q":"吾归破贼，必灭贺兰！此矢所以志也。","a":"我回去打败叛贼之后，必定消灭贺兰！这支箭就是我用来作标记的。","note":"志：通“识”，标记；所以：用来……的。","src":"张中丞传后叙"},{"q":"两家子弟材智下，不能通知二父志，以为巡死而远就虏，疑畏死而辞服于贼。","a":"两家子弟才能低下，不能透彻理解他们父辈的志向，认为张巡战死而许远被俘，怀疑许远是怕死而向敌人屈服了。","note":"通知：通晓（古今异义）；辞服：屈服。此为全文批驳的靶子。","src":"张中丞传后叙"},{"q":"伯夷辞之以为名，仲尼语之以为博。","a":"伯夷辞让它来求得名声，孔子谈论它来显示渊博。","note":"之：代天下。暗刺伯夷、孔子亦\"自多\"。","src":"秋水"},{"q":"君若以德绥诸侯，谁敢不服？","a":"您如果用德行安抚诸侯，谁敢不服？","note":"绥：安抚。屈完先以“德”为对。","src":"齐桓公伐楚"},{"q":"夫物不产于秦，可宝者多；士不产于秦，而愿忠者众。","a":"物品不出产在秦国，可宝贵的却很多；贤士不出生在秦国，愿意效忠的却很多。","note":"“宝”形容词意动/形作动，以为宝。并列对举，收束物与人两层。","src":"谏逐客书"},{"q":"群臣吏民能面刺寡人之过者，受上赏。","a":"大小官吏百姓能够当面指责我过错的，受上等奖赏。","note":"“能面刺寡人之过者”为“者”字结构作定语后置（即“能面刺寡人之过之群臣吏民”）；“面”名词作状语。","src":"邹忌讽齐王纳谏"},{"q":"赵氏求救于齐，齐曰：“必以长安君为质，兵乃出。”","a":"赵国向齐国求救，齐国说：“一定要用长安君作人质，救兵才派出。”","note":"“求救于齐”状语后置，即“于齐求救”；“乃”：才。","src":"触龙说赵太后"},{"q":"孟子对曰：\"仲尼之徒无道桓文之事者，是以后世无传焉，臣未之闻也。无以，则王乎？\"","a":"孟子回答说：\"孔子的门徒中没有谈论齐桓公、晋文公霸业的，所以后世没有流传，我没有听说过。如果一定要我说，那就说说行王道吧？\"","note":"道：谈论；传：流传；无以：不得已、一定要说；「未之闻」宾语前置，即「未闻之」。","src":"齐桓晋文之事"},{"q":"余虽与晋出入，余唯利是视。","a":"我虽然同晋往来，我只图利。","note":"“唯利是视”即“唯视利”，宾语前置。引楚人转述秦语，揭秦唯利是图。","src":"吕相绝秦"},{"q":"都城过百雉，国之害也。","a":"都邑城墙超过百雉，是国家的祸害。","note":"判断句。都：卿大夫都邑；雉：长三丈高一丈为一雉。","src":"郑伯克段于鄢"},{"q":"人之将死，其藏腑必有先受其病者；引绳而绝之，其绝必有处。","a":"人将要死的时候，他的内脏必定有先得病的部位；拉紧绳子而断它，绳子的断裂必定有个地方。","note":"藏腑：即脏腑。以两个比喻说明城陷必有先后，不能因此归咎许远。","src":"张中丞传后叙"},{"q":"至人无己，神人无功，圣人无名。","a":"道德修养最高的人忘却自我，神人不求功业，圣人不求声名。","note":"全文主旨句。三者递降（至人最高），点明逍遥的理想人格：无己、无功、无名。","src":"逍遥游"},{"q":"莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。","a":"暮春时节，穿上春装，约上五六个成年人、六七个少年，在沂水边洗洗澡，在舞雩台上吹吹风，唱着歌回来。","note":"莫通“暮”；“浴乎沂”“风乎舞雩”状语后置；“风”名词作动词。","src":"子路曾皙冉有公西华侍坐"},{"q":"三子者出，曾皙后。曾皙曰：“夫三子者之言何如？”","a":"那三个人出去了，曾皙留在后面。曾皙问：\"那三位的话怎么样？\"","note":"后：名词作动词，留在后面。","src":"子路曾皙冉有公西华侍坐"},{"q":"君处北海，寡人处南海，唯是风马牛不相及也。","a":"君侯住在北方，寡人住在南方，即使马牛走失，也不会跑到对方境内。","note":"风：放、走失（一说牝牡相诱）。喻齐楚相距极远、互不相干。","src":"齐桓公伐楚"},{"q":"今君王既栖于会稽之上，然后乃求谋臣，无乃后乎？","a":"如今君王已经退守会稽，这才来求谋臣，恐怕太晚了吧？","note":"无乃……乎：恐怕……吧，表委婉反问。","src":"勾践灭吴"},{"q":"冉有曰：“今夫颛臾，固而近于费。今不取，后世必为子孙忧。”","a":"冉有说：\"如今那颛臾，城墙坚固而且靠近费邑。现在不攻取，后世一定会成为子孙的忧患。\"","note":"固：坚固；近于费：状语后置，即「于费近」，靠近费邑。","src":"季氏将伐颛臾"},{"q":"孔子曰：“求！周任有言曰：‘陈力就列，不能者止。’危而不持，颠而不扶，则将焉用彼相矣？且尔言过矣。虎兕出于柙，龟玉毁于椟中，是谁之过与？”","a":"孔子说：\"冉求！周任有句话说：'施展才能来担任职务，不能胜任的就辞职。'盲人遇到危险不去搀扶，跌倒了不去扶起，那又何必用那个辅助的人呢？况且你的话错了。老虎犀牛从笼子里跑出来，龟甲美玉在匣子里毁坏了，这是谁的过错呢？\"","note":"陈力就列：施展才能担任职务；相：辅助盲人的人，喻辅佐者；兕：犀牛；柙：笼子；椟：匣子。","src":"季氏将伐颛臾"}]},{"no":10,"date":"2026-11-07","date_end":"2026-11-08","pieces":["谏逐客书","留侯论","齐桓晋文之事","巫山巫峡","郑伯克段于鄢","秋水"],"theme":"综合练习 10","p1":[{"q":"「关关雎鸠，在河之洲。窈窕淑女，君子好逑。」出自（　）","opts":["满江红","诗经","离骚","卜居"],"ans":"B","atext":"诗经","src":"名句→出处","note":"\"关关雎鸠，在河之洲。窈窕淑女，君子好逑。\"——出自《诗经·周南·关雎》，为《诗经》首篇，写君子对淑女的思慕。"},{"q":"「会当凌绝顶，一览众山小。」出自（　）","opts":["离思","望岳","游山西村","浣溪沙"],"ans":"B","atext":"望岳","src":"名句→出处","note":"“会当凌绝顶，一览众山小。”——杜甫《望岳》。"},{"q":"「纸上得来终觉浅，绝知此事要躬行。」出自（　）","opts":["自京赴奉先县咏怀五百字","茅屋为秋风所破歌","冬夜读书示子聿","送杜少府之任蜀州"],"ans":"C","atext":"冬夜读书示子聿","src":"名句→出处","note":"“纸上得来终觉浅，绝知此事要躬行。”——陆游《冬夜读书示子聿》。"},{"q":"「岁寒，然后知松柏之后凋也。」出自（　）","opts":["论语","夏日绝句","登飞来峰","谏逐客书"],"ans":"A","atext":"论语","src":"名句→出处","note":"“岁寒，然后知松柏之后凋也。”——《论语·子罕》。"},{"q":"「海内存知己，天涯若比邻。」出自（　）","opts":["茅屋为秋风所破歌","晓出净慈寺送林子方","送杜少府之任蜀州","白雪歌送武判官归京"],"ans":"C","atext":"送杜少府之任蜀州","src":"名句→出处","note":"“海内存知己，天涯若比邻。”——王勃《送杜少府之任蜀州》。"},{"q":"「问君能有几多愁？恰似一江春水向东流。」出自（　）","opts":["声声慢","题西林壁","虞美人","离思"],"ans":"C","atext":"虞美人","src":"名句→出处","note":"“问君能有几多愁？恰似一江春水向东流。”——李煜《虞美人》。"},{"q":"「无可奈何花落去，似曾相识燕归来。」出自（　）","opts":["雨霖铃","陋室铭","南乡子","浣溪沙"],"ans":"D","atext":"浣溪沙","src":"名句→出处","note":"“无可奈何花落去，似曾相识燕归来。”——晏殊《浣溪沙》。"},{"q":"「人生自古谁无死，留取丹心照汗青。」出自（　）","opts":["饮酒","满江红","过零丁洋","后赤壁赋"],"ans":"C","atext":"过零丁洋","src":"名句→出处","note":"“人生自古谁无死，留取丹心照汗青。”——文天祥《过零丁洋》。"},{"q":"「明月松间照，清泉石上流。」出自（　）","opts":["山居秋暝","锦瑟","无题","后赤壁赋"],"ans":"A","atext":"山居秋暝","src":"名句→出处","note":"“明月松间照，清泉石上流。”——王维《山居秋暝》。"},{"q":"「寄蜉蝣于天地，渺沧海之一粟。」出自（　）","opts":["登鹳雀楼","将进酒","赤壁赋","卜居"],"ans":"C","atext":"赤壁赋","src":"名句→出处","note":"“寄蜉蝣于天地，渺沧海之一粟。”——苏轼《赤壁赋》。"},{"q":"「曾经沧海难为水，除却巫山不是云。」出自（　）","opts":["卜居","离骚","离思","春晓"],"ans":"C","atext":"离思","src":"名句→出处","note":"“曾经沧海难为水，除却巫山不是云。”——元稹《离思》。"},{"q":"「青，取之于蓝，而青于蓝。」出自（　）","opts":["将进酒","声声慢","青玉案","劝学"],"ans":"D","atext":"劝学","src":"名句→出处","note":"“青，取之于蓝，而青于蓝。”——荀子《劝学》。"},{"q":"「泰山不让土壤，故能成其大；河海不择细流，故能就其深。」出自（　）","opts":["芙蓉楼送辛渐","寄扬州韩绰判官","谏逐客书","梦游天姥吟留别"],"ans":"C","atext":"谏逐客书","src":"名句→出处","note":"“泰山不让土壤，故能成其大；河海不择细流，故能就其深。”——李斯《谏逐客书》。"},{"q":"「青山遮不住，毕竟东流去。」出自（　）","opts":["夏日绝句","菩萨蛮","滕王阁序","锦瑟"],"ans":"B","atext":"菩萨蛮","src":"名句→出处","note":"“青山遮不住，毕竟东流去。”——辛弃疾《菩萨蛮·书江西造口壁》。"},{"q":"「劝君更尽一杯酒，西出阳关无故人。」出自（　）","opts":["别董大","长恨歌","送元二使安西","南乡子"],"ans":"C","atext":"送元二使安西","src":"名句→出处","note":"“劝君更尽一杯酒，西出阳关无故人。”——王维《送元二使安西》。"},{"q":"「安得广厦千万间，大庇天下寒士俱欢颜。」出自（　）","opts":["过零丁洋","后赤壁赋","登鹳雀楼","茅屋为秋风所破歌"],"ans":"D","atext":"茅屋为秋风所破歌","src":"名句→出处","note":"\"安得广厦千万间，大庇天下寒士俱欢颜。\"——出自杜甫《茅屋为秋风所破歌》，表现推己及人的博大胸怀。"},{"q":"「锲而舍之，朽木不折；锲而不舍，金石可镂。」出自（　）","opts":["虞美人","山居秋暝","劝学","进学解"],"ans":"C","atext":"劝学","src":"名句→出处","note":"“锲而舍之，朽木不折；锲而不舍，金石可镂。”——荀子《劝学》。"},{"q":"「上善若水，水善利万物而不争。」出自（　）","opts":["陋室铭","老子","红楼梦","行路难"],"ans":"B","atext":"老子","src":"名句→出处","note":"\"上善若水，水善利万物而不争。\"——出自《老子》第八章，以水喻最高的善。"},{"q":"《季氏将伐颛臾》的体裁是（　）","opts":["奏疏（政论文）","哲理散文（道家诸子散文，寓言体）","语录体散文（儒家经典）","山水游记（“记”体散文）"],"ans":"C","atext":"语录体散文（儒家经典）","src":"篇目→体裁","note":"《季氏将伐颛臾》语录体散文（儒家经典）。"},{"q":"「不积跬步，无以至千里；不积小流，无以成江海。」的作者是（　）","opts":["白居易","荀子","于谦","晏殊"],"ans":"B","atext":"荀子","src":"名句→作者","note":"“不积跬步，无以至千里；不积小流，无以成江海。”——荀子《劝学》。"}],"p2":[{"q":"「此小大之辩也。」中「辩」的意思是（　）","opts":["半步（音kuǐ）","通晓、贯通","通\"辨\"，分别，区别。","讨伐、攻打"],"ans":"C","atext":"通\"辨\"，分别，区别。","src":"实词释义","note":"《逍遥游》此小大之辩也。　辩(biàn)：区别；下文\"御六气之辩\"则通\"变\"。"},{"q":"「闻道百，以为莫己若者。」中「若」的意思是（　）","opts":["量（长短）。","如，比得上（动词）。","胜过、超过","旧事、前例"],"ans":"B","atext":"如，比得上（动词）。","src":"实词释义","note":"《秋水》闻道百，以为莫己若者。　若：比得上；莫己若即\"莫若己\"，宾语前置。"},{"q":"「广畜积」中「畜」的意思是（　）","opts":["成年人（古男子二十岁行冠礼）","吝惜，吝啬。","通“隙”，空隙，引申为身体不适","通“蓄”，积蓄（音xù）"],"ans":"D","atext":"通“蓄”，积蓄（音xù）","src":"实词释义","note":"《论贵粟疏》广畜积　“畜”通“蓄”。"},{"q":"「窃以为过矣」中「过」的意思是（　）","opts":["遭受、蒙受","偷看、观察","错误、过失","植根、立足"],"ans":"C","atext":"错误、过失","src":"实词释义","note":"《谏逐客书》窃以为过矣　名词，作“以为”的宾语。"},{"q":"「不虞君之涉吾地也」中「涉」的意思是（　）","opts":["辞让、拒绝","进入，涉足","责问，问罪","快、迅速"],"ans":"B","atext":"进入，涉足","src":"实词释义","note":"《齐桓公伐楚》不虞君之涉吾地也　委婉说法，实指侵入。"},{"q":"「能面刺寡人之过者」中「面」的意思是（　）","opts":["光艳美丽","责备","砍削","当面"],"ans":"D","atext":"当面","src":"实词释义","note":"《邹忌讽齐王纳谏》能面刺寡人之过者　名词作状语修饰“刺”。"},{"q":"「深折其少年刚锐之气」中「折」的意思是（　）","opts":["挫败、屈辱","杀戮，杀害","施加、侵凌","怀抱（指抱负）"],"ans":"A","atext":"挫败、屈辱","src":"实词释义","note":"《留侯论》深折其少年刚锐之气　折：折辱、挫折，使动。"},{"q":"「岂卖菜也而索直乎」中「直」的意思是（　）","opts":["价钱","偏爱","甚、很","善，体恤"],"ans":"A","atext":"价钱","src":"实词释义","note":"《小翠》岂卖菜也而索直乎　直通“值”，价钱。"},{"q":"「《齐谐》者，志怪者也。」中「志」的意思是（　）","opts":["延续、遍及（音yì）","攻取、攻克","通“磨”，磨灭","记载，记录。"],"ans":"D","atext":"记载，记录。","src":"实词释义","note":"《逍遥游》《齐谐》者，志怪者也。　志怪：记载怪异的事物。"},{"q":"「河海不择细流」中「择」的意思是（　）","opts":["舍弃、剔除","站起身","增补、增加","全都、一概"],"ans":"A","atext":"舍弃、剔除","src":"实词释义","note":"《谏逐客书》河海不择细流　一说通“释”，舍弃。"}],"p3":[{"q":"今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓“借寇兵而赍盗粮”者也。","a":"如今却抛弃百姓去资助敌国，拒绝宾客去使诸侯成就霸业，使天下贤士退缩不敢西进，停步不敢入秦，这就是所说的“把武器借给敌寇、把粮食送给盗贼”啊。","note":"“乃”却；“业”使动；“赍”赠送；判断句以“此所谓……者也”收束，比喻逐客之害。","src":"谏逐客书"},{"q":"是故倨傲鲜腆而深折之。","a":"所以老人故意态度傲慢无礼地重重折辱他。","note":"鲜腆：无礼；折：折辱。揭示老人试“忍”的用意。","src":"留侯论"},{"q":"曰：\"臣闻之胡龁曰：'王坐于堂上，有牵牛而过堂下者。王见之，曰：牛何之？对曰：将以衅钟。王曰：舍之！吾不忍其觳觫，若无罪而就死地。对曰：然则废衅钟与？曰：何可废也？以羊易之。'不识有诸？\"","a":"孟子说：\"我从胡龁那里听说：大王坐在堂上，有人牵着牛从堂下经过。大王看见了，问：牛要牵到哪里去？回答说：要用它的血涂钟。大王说：放了它！我不忍心看它恐惧发抖的样子，就像没有罪过却要被处死。回答说：那么废弃涂钟的仪式吗？大王说：怎么能废弃呢？用羊换它。不知道有这回事吗？\"","note":"之：向，闻之于胡龁；何之：到哪里去，宾语前置；衅钟：杀牲涂血祭钟；觳觫：恐惧发抖；就死地：走向死地。","src":"齐桓晋文之事"},{"q":"自三峡七百里中，两岸连山，略无阙处；重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。","a":"在三峡七百里之间，两岸群山相连，几乎没有中断的地方；层层悬崖、排排峭壁遮天蔽日，如果不是正午和半夜，就看不见太阳和月亮。","note":"略：完全；阙：通“缺”；亭午：正午。全句正面写山之高连绵，用“自非……不见……”的双重否定反衬山势高峻。","src":"巫山巫峡"},{"q":"当此之时，子房之不死者，其间不能容发，盖亦已危矣。","a":"在那个时候，张良死里逃生，其间的危险连一根头发都容不下，真是太危险了。","note":"间不能容发：极言危险。盖：大概。","src":"留侯论"},{"q":"大叔完聚，缮甲兵，具卒乘，将袭郑。夫人将启之。公闻其期，曰：“可矣！”命子封帅车二百乘以伐京。京叛大叔段。段入于鄢，公伐诸鄢。五月辛丑，大叔出奔共。","a":"太叔修治城郭、聚集百姓，修缮铠甲兵器，准备步兵战车，打算偷袭郑国国都。武姜准备为他打开城门。庄公探听到他起兵的日期，说：\"可以了！\"命令子封率领二百辆战车去攻打京邑。京邑的人背叛了太叔段，段逃到鄢地，庄公又到鄢地讨伐他。五月辛丑日，太叔出逃到共国。","note":"完聚：修治城郭、聚集百姓；缮：修缮；具：准备；启之：为他开城门；诸：兼词「之于」。","src":"郑伯克段于鄢"},{"q":"此其所挟持者甚大，而其志甚远也。","a":"这是因为他内心所怀抱的抱负很大，而他的志向又很远大。","note":"挟持者：指抱负。说明能忍的根源在于志大。","src":"留侯论"},{"q":"故深折其少年刚锐之气，使之忍小忿而就大谋。","a":"所以深深挫折他年轻人刚强锐利的脾气，使他能忍住小的愤怒而成就远大的谋略。","note":"忍小忿而就大谋：化用《论语》“小不忍则乱大谋”。","src":"留侯论"},{"q":"天下之水，莫大于海。","a":"天下的水，没有比海更大的。","note":"\"莫大于海\"：状语后置（于海大）。极写海之大。","src":"秋水"},{"q":"故渔者歌曰：巴东三峡巫峡长，猿鸣三声泪沾裳。","a":"所以打鱼的人唱道：巴东三峡之中巫峡最长，猿猴啼叫几声就令人泪水沾湿衣裳。","note":"引渔歌作结，“长”与“泪”呼应，把景语化为情语。","src":"巫山巫峡"},{"q":"媪之送燕后也，持其踵，为之泣，念悲其远也，亦哀之矣。","a":"您送燕后出嫁时，握着她的脚后跟为她哭泣，想到她远嫁而悲伤，也够哀怜她了。","note":"踵：脚后跟；持踵：古礼女儿出嫁，亲人不忍其行；“之”用于主谓间。","src":"触龙说赵太后"},{"q":"君子之于禽兽也：见其生，不忍见其死；闻其声，不忍食其肉。是以君子远庖厨也。","a":"君子对于飞禽走兽，看见它活着，便不忍心看它死去；听到它哀鸣的声音，便不忍心吃它的肉。因此君子远离厨房。","note":"远：形作动，远离。\"是以\"即\"以是\"，宾语前置。","src":"齐桓晋文之事"},{"q":"上惊验之，其旒冕乃梁黠心所制，袍则败布黄袱也。上怒其诬。","a":"皇帝惊讶地查验，那旒冕原来是高粱秸心做的，龙袍不过是旧黄布包袱。皇帝对王给谏的诬告大怒。","note":"写小翠以假乱真，智破政敌。","src":"小翠"},{"q":"王曰：\"吾惛，不能进于是矣。愿夫子辅吾志，明以教我；我虽不敏，请尝试之。\"","a":"宣王说：\"我昏乱糊涂，不能进到这一步了。希望先生帮助我实现志向，明确地教导我；我虽然不聪明，也请让我试一试。\"","note":"惛：昏乱糊涂；进于是：达到这一步；敏：聪敏。","src":"齐桓晋文之事"},{"q":"小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋；上古有大椿者，以八千岁为春，八千岁为秋。而彭祖乃今以久特闻，众人匹之，不亦悲乎！","a":"小智不能了解大智，寿命短的不了解寿命长的。怎么知道是这样呢？朝菌不知道一个月的时间，寒蝉不知道一年的时间，这就是寿命短的。楚国南边有一种叫冥灵的大树，把五百年当作一个春季，五百年当作一个秋季；上古有一种大椿树，把八千年当作一个春季，八千年当作一个秋季。可是彭祖如今却以长寿特别闻名，人们都和他相比，不也很可悲吗！","note":"知：通「智」；年：寿命；晦朔：一个月；蟪蛄：寒蝉；匹之：和他相比。","src":"逍遥游"},{"q":"对曰：“非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。”","a":"公西赤回答说：\"不敢说能做到，但愿意学习。宗庙祭祀的事，或者诸侯会盟的事，我愿意穿着礼服、戴着礼帽，做一个小小的司仪。\"","note":"会同：诸侯会盟；端章甫：穿礼服戴礼帽，名词作动词；小相：小司仪。","src":"子路曾皙冉有公西华侍坐"},{"q":"及陷于罪，然后从而刑之，是罔民也。","a":"等到他们犯了罪，接着就用刑罚处置他们，这是陷害百姓。","note":"罔通\"网\"，名作动，陷害。判断句。","src":"齐桓晋文之事"},{"q":"陈力就列，不能者止。","a":"能施展才力就任职，不能这样就辞职。","note":"引古史官周任之言，责冉有、季路不能止谏。","src":"季氏将伐颛臾"},{"q":"太史公疑子房以为魁梧奇伟，而其状貌乃如妇人女子，不称其志气。呜呼！此其所以为子房欤！","a":"司马迁原以为张良魁梧奇伟，可他的相貌却像妇人女子，同他的志气并不相称。唉！这正是张良之所以为张良啊！","note":"称（chèn）：相称。借司马迁之叹作结，余味不尽。","src":"留侯论"},{"q":"且夫水之积也不厚，则其负大舟也无力。","a":"况且水积聚得不深厚，那么它浮载大船就没有力量。","note":"\"之\"用于主谓之间取消句子独立性；负：浮载。以水与舟喻风与鹏，说明万物有所待。","src":"逍遥游"}]},{"no":11,"date":"2026-11-08","date_end":"2026-11-09","pieces":["吕相绝秦","秋水","六国论","齐桓晋文之事","许行","郑伯克段于鄢"],"theme":"综合练习 11","p1":[{"q":"「山高月小，水落石出。」的作者是（　）","opts":["柳永","辛弃疾","朱熹","苏轼"],"ans":"D","atext":"苏轼","src":"名句→作者","note":"“山高月小，水落石出。”——苏轼《后赤壁赋》。"},{"q":"《吕相绝秦》的体裁是（　）","opts":["奏疏（政论文）","书楼记（杂记，“记”体）","文言短篇小说（志怪/传奇）","编年体史书（先秦历史散文）"],"ans":"D","atext":"编年体史书（先秦历史散文）","src":"篇目→体裁","note":"《吕相绝秦》编年体史书（先秦历史散文）。"},{"q":"「泰山不让土壤，故能成其大；河海不择细流，故能就其深。」的作者是（　）","opts":["杜牧","周敦颐","文天祥","李斯"],"ans":"D","atext":"李斯","src":"名句→作者","note":"“泰山不让土壤，故能成其大；河海不择细流，故能就其深。”——李斯《谏逐客书》。"},{"q":"《烛之武退秦师》的体裁是（　）","opts":["山水游记散文（地理著作）","哲理散文（道家诸子散文，对话体寓言）","山水游记（“记”体散文）","编年体史书（先秦历史散文）"],"ans":"D","atext":"编年体史书（先秦历史散文）","src":"篇目→体裁","note":"《烛之武退秦师》编年体史书（先秦历史散文）。"},{"q":"《触龙说赵太后》的体裁是（　）","opts":["国别体史书（先秦历史散文）","书楼记（杂记，“记”体）","后序（传记议论文，古文运动散文）","哲理散文（道家诸子散文，对话体寓言）"],"ans":"A","atext":"国别体史书（先秦历史散文）","src":"篇目→体裁","note":"《触龙说赵太后》国别体史书（先秦历史散文）。"},{"q":"《留侯论》的体裁是（　）","opts":["史论（议论文，“论”体）","山水游记散文（地理著作）","对话体论说文（诸子散文，论辩体）","对话体论说文（诸子散文，语录体）"],"ans":"A","atext":"史论（议论文，“论”体）","src":"篇目→体裁","note":"《留侯论》史论（议论文，“论”体）。"},{"q":"《传是楼记》的体裁是（　）","opts":["哲理散文（道家诸子散文，寓言体）","国别体史书（先秦历史散文）","书楼记（杂记，“记”体）","史论（议论文，“论”体）"],"ans":"C","atext":"书楼记（杂记，“记”体）","src":"篇目→体裁","note":"《传是楼记》书楼记（杂记，“记”体）。"},{"q":"「大江东去，浪淘尽，千古风流人物。」的作者是（　）","opts":["王勃","马致远","苏轼","王维"],"ans":"C","atext":"苏轼","src":"名句→作者","note":"\"大江东去，浪淘尽，千古风流人物。\"——出自苏轼《念奴娇·赤壁怀古》，豪放词代表句。"},{"q":"「君子博学而日参省乎己，则知明而行无过矣。」的作者是（　）","opts":["荀子","李商隐","王安石","欧阳修"],"ans":"A","atext":"荀子","src":"名句→作者","note":"“君子博学而日参省乎己，则知明而行无过矣。”——荀子《劝学》。"},{"q":"「寄蜉蝣于天地，渺沧海之一粟。」的作者是（　）","opts":["于谦","周敦颐","孟浩然","苏轼"],"ans":"D","atext":"苏轼","src":"名句→作者","note":"“寄蜉蝣于天地，渺沧海之一粟。”——苏轼《赤壁赋》。"},{"q":"「锲而舍之，朽木不折；锲而不舍，金石可镂。」的作者是（　）","opts":["屈原","杨万里","范仲淹","荀子"],"ans":"D","atext":"荀子","src":"名句→作者","note":"“锲而舍之，朽木不折；锲而不舍，金石可镂。”——荀子《劝学》。"},{"q":"「但愿人长久，千里共婵娟。」的作者是（　）","opts":["李白","苏轼","岑参","李清照"],"ans":"B","atext":"苏轼","src":"名句→作者","note":"\"但愿人长久，千里共婵娟。\"——出自苏轼《水调歌头·明月几时有》，寄托对亲人的美好祝愿。"},{"q":"「业精于勤，荒于嬉；行成于思，毁于随。」的作者是（　）","opts":["陆游","韩愈","孟浩然","陶渊明"],"ans":"B","atext":"韩愈","src":"名句→作者","note":"“业精于勤，荒于嬉；行成于思，毁于随。”——韩愈《进学解》。"},{"q":"《齐桓晋文之事》的体裁是（　）","opts":["对话体论说文（诸子散文，语录体）","山水游记散文（地理著作）","编年体史书（先秦历史散文）","语录体散文（儒家经典）"],"ans":"A","atext":"对话体论说文（诸子散文，语录体）","src":"篇目→体裁","note":"《齐桓晋文之事》对话体论说文（诸子散文，语录体）。"},{"q":"《秋水》的体裁是（　）","opts":["史论（议论文，“论”体）","哲理散文（道家诸子散文，对话体寓言）","对话体论说文（诸子散文，语录体）","文言短篇小说（志怪/传奇）"],"ans":"B","atext":"哲理散文（道家诸子散文，对话体寓言）","src":"篇目→体裁","note":"《秋水》哲理散文（道家诸子散文，对话体寓言）。"},{"q":"《谏逐客书》的体裁是（　）","opts":["奏议（奏章、疏）","奏疏（政论文）","文言短篇小说（志怪/传奇）","语录体散文（儒家经典）"],"ans":"A","atext":"奏议（奏章、疏）","src":"篇目→体裁","note":"《谏逐客书》奏议（奏章、疏）。"},{"q":"《鸿门宴》的体裁是（　）","opts":["山水游记（“记”体散文）","纪传体史传文（历史散文）","哲理议论文（先秦诸子散文）","山水游记散文（地理著作）"],"ans":"B","atext":"纪传体史传文（历史散文）","src":"篇目→体裁","note":"《鸿门宴》纪传体史传文（历史散文）。"},{"q":"「青，取之于蓝，而青于蓝。」的作者是（　）","opts":["曹操","李煜","王昌龄","荀子"],"ans":"D","atext":"荀子","src":"名句→作者","note":"“青，取之于蓝，而青于蓝。”——荀子《劝学》。"},{"q":"《齐桓公伐楚》的体裁是（　）","opts":["哲理散文（道家诸子散文，寓言体）","哲理议论文（先秦诸子散文）","编年体史书（先秦历史散文）","国别体史书（先秦历史散文）"],"ans":"C","atext":"编年体史书（先秦历史散文）","src":"篇目→体裁","note":"《齐桓公伐楚》编年体史书（先秦历史散文）。"},{"q":"《巫山巫峡》的体裁是（　）","opts":["山水游记散文（地理著作）","哲理散文（道家诸子散文，对话体寓言）","哲理散文（道家诸子散文，寓言体）","对话体论说文（诸子散文，论辩体）"],"ans":"A","atext":"山水游记散文（地理著作）","src":"篇目→体裁","note":"《巫山巫峡》山水游记散文（地理著作）。"}],"p2":[{"q":"「汉水以为池」中「池」的意思是（　）","opts":["通“三”","灾患、损耗","备办、摆设","护城河"],"ans":"D","atext":"护城河","src":"实词释义","note":"《齐桓公伐楚》汉水以为池　与“城（城墙）”相对。"},{"q":"「授之柄而处其下」中「柄」的意思是（　）","opts":["按时，按季节。","竟、简直","遭受、蒙受","权柄、军事指挥权"],"ans":"D","atext":"权柄、军事指挥权","src":"实词释义","note":"《张中丞传后叙》授之柄而处其下　许远把兵权交给张巡而自居其下。"},{"q":"「窃以为过矣」中「窃」的意思是（　）","opts":["胜任，勉强能够。","违背、抵触","私下、谦指自己","如果真的"],"ans":"C","atext":"私下、谦指自己","src":"实词释义","note":"《谏逐客书》窃以为过矣　表谦敬的副词性用法。"},{"q":"「烈火而焚之」中「烈火」的意思是（　）","opts":["舍，进驻，安居","旧事、前例","点燃大火","称王"],"ans":"C","atext":"点燃大火","src":"实词释义","note":"《钴鉧潭西小丘记》烈火而焚之　“烈”形容词活用为动词，燃起烈火。"},{"q":"「谋臣与爪牙之士」中「爪牙」的意思是（　）","opts":["堵塞、杜绝","奋发，这里指鼓起翅膀、用力鼓动。","比喻勇武的卫士、武将","两属，怀有二心"],"ans":"C","atext":"比喻勇武的卫士、武将","src":"实词释义","note":"《勾践灭吴》谋臣与爪牙之士　古义为得力武臣，非贬义。"},{"q":"「此其所挟持者甚大」中「挟持」的意思是（　）","opts":["半步（音kuǐ）","疏通，疏导。","怀抱（指抱负）","常，永久固定的。"],"ans":"C","atext":"怀抱（指抱负）","src":"实词释义","note":"《留侯论》此其所挟持者甚大　挟持者：指内心所怀抱的理想抱负。"},{"q":"「能谤讥于市朝」中「谤讥」的意思是（　）","opts":["在公众场合指责、议论（讥：谏）","名词作动词，称王（音wàng）","通\"盍\"，何不。","通“疲”，疲弱无能"],"ans":"A","atext":"在公众场合指责、议论（讥：谏）","src":"实词释义","note":"《邹忌讽齐王纳谏》能谤讥于市朝　古义不含贬义，指公开议论过失；“市朝”指集市、朝廷等公共场所。"},{"q":"「遂使之行成于吴」中「行成」的意思是（　）","opts":["舍弃、剔除","依靠、凭借","怎么，哪里","求和，议和"],"ans":"D","atext":"求和，议和","src":"实词释义","note":"《勾践灭吴》遂使之行成于吴　行成：求和。"},{"q":"「无乃后乎」中「无乃」的意思是（　）","opts":["舍，进驻，安居","恐怕，莫非（表推测）","加倍、利息加倍（称chèn）","肃杀、凄清"],"ans":"B","atext":"恐怕，莫非（表推测）","src":"实词释义","note":"《勾践灭吴》无乃后乎　“无乃……乎”固定句式。"},{"q":"「隧而相见」中「隧」的意思是（　）","opts":["欺骗","护城河","向东","挖隧道"],"ans":"D","atext":"挖隧道","src":"实词释义","note":"《郑伯克段于鄢》隧而相见　名词用作动词。"}],"p3":[{"q":"我君景公引领西望曰：庶抚我乎！","a":"我们景公伸长脖子西望说：大概会安抚我们了吧！","note":"引领：伸颈。写盼秦和好之切。","src":"吕相绝秦"},{"q":"井蛙不可以语于海者，拘于虚也。","a":"井里的蛙不能和它谈海，是因为它被居处所局限。","note":"判断句；虚通\"墟\"，居处。\"拘于虚\"为被动/状语后置。比喻眼界受空间限制。","src":"秋水"},{"q":"六国破灭，非兵不利，战不善，弊在赂秦。赂秦而力亏，破灭之道也。或曰：“六国互丧，率赂秦耶？”曰：“不赂者以赂者丧，盖失强援，不能独完。故曰：弊在赂秦也。”","a":"六国灭亡，不是兵器不锋利，仗打得不好，弊病在于贿赂秦国。贿赂秦国就使国力亏损，这是灭亡的原因。有人说：\"六国相继灭亡，都是因为贿赂秦国吗？\"回答说：\"不贿赂的国家因为贿赂的国家而灭亡，因为失去了强大的援助，不能独自保全。所以说：弊病在于贿赂秦国。\"","note":"兵：兵器；弊在赂秦：弊病在于贿赂秦国；率：全都；完：保全。","src":"六国论"},{"q":"王笑曰：\"是诚何心哉？我非爱其财而易之以羊也，宜乎百姓之谓我爱也。\"","a":"宣王笑着说：\"这究竟是什么心理呢？我不是吝惜钱财才用羊换它，百姓说我吝惜也是应该的。\"","note":"爱：吝惜；宜乎百姓之谓我爱也：主谓倒装，即「百姓谓我爱也宜乎」。","src":"齐桓晋文之事"},{"q":"\"然则治天下独可耕且为与？有大人之事，有小人之事。且一人之身，而百工之所为备。如必自为而后用之，是率天下而路也。故曰：或劳心，或劳力；劳心者治人，劳力者治于人；治于人者食人，治人者食于人：天下之通义也。","a":"\"那么治理天下难道可以一边耕种一边做吗？有做官的人的事，有百姓的事。而且一个人的生活所需，要靠各种工匠的成品来齐备。如果一定要自己做了才用，这是引导天下的人疲于奔命。所以说：有的人动脑筋，有的人出力；动脑筋的人治理别人，出力的人被别人治理；被别人治理的人供养别人，治理别人的人被别人供养：这是天下通行的道理。","note":"大人：做官的人；小人：百姓；备：齐备；路：通「露」，疲于奔命；劳心者治人：动脑的人治理别人。","src":"许行"},{"q":"夏虫不可以语于冰者，笃于时也。","a":"夏天的虫不能和它谈冰，是因为它被时令所局限。","note":"判断句；笃：局限。比喻受时间限制，即\"夏虫语冰\"。","src":"秋水"},{"q":"尔有母遗，繄我独无！","a":"你有母亲可以孝敬，唯独我没有！","note":"遗（wèi）：孝敬。繄（yī）：惟、独。庄公悔恨之言。","src":"郑伯克段于鄢"},{"q":"百姓皆以王为爱也，臣固知王之不忍也。","a":"百姓都认为大王是吝啬，我本来就知道您是于心不忍。","note":"爱：吝啬；以：认为。\"王之不忍\"之字取消句子独立性。","src":"齐桓晋文之事"},{"q":"或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。","a":"有时遇到皇帝命令急需传达，早晨从白帝城出发，傍晚就到江陵，这中间一千二百里，即使骑着飞奔的马、驾着长风，也没有这样快。","note":"朝、暮：名词作状语，在早晨、在傍晚；奔：活用为名词“奔马”。以夸张与对比写水流之速。","src":"巫山巫峡"},{"q":"无庸，将自及。","a":"不用除他，他会自己招致灾祸。","note":"庸通用；及：及于祸。","src":"郑伯克段于鄢"},{"q":"蜩与学鸠笑之曰：\"我决起而飞，抢榆枋而止，时则不至，而控于地而已矣，奚以之九万里而南为？\"适莽苍者，三餐而反，腹犹果然；适百里者，宿舂粮；适千里者，三月聚粮。之二虫又何知！","a":"蝉和斑鸠讥笑它说：\"我一下子起飞，碰到榆树檀树就停下来，有时飞不到，就落到地上罢了，哪里用得着飞上九万里再往南去呢？\"到近郊去的人，只带三顿饭就可以往返，肚子还是饱饱的；到百里外去的人，要前一天夜里舂米备粮；到千里外去的人，要用三个月积聚干粮。这两只小虫又知道什么呢！","note":"决起：一下子起飞；抢：碰到；控：落下；莽苍：近郊；果然：饱足的样子；之二虫：这两只小虫，指示代词。","src":"逍遥游"},{"q":"闻其故，惊颜如土，大哭曰：“此祸水也！指日赤吾族矣！”","a":"听了缘故，王太常脸色如土，大哭道：“这是祸水啊！很快就要使我家族杀身灭门了！”","note":"赤：使动，杀尽。写王公惊惶。","src":"小翠"},{"q":"三江环之，民无所移。有吴则无越，有越则无吴。","a":"三江环绕吴越，百姓无法外迁。有吴就没有越，有越就没有吴。","note":"子胥陈说吴越势不两立。","src":"勾践灭吴"},{"q":"越国以鄙远，君知其难也，焉用亡郑以陪邻？","a":"越过晋国而把远方的郑国作边邑，您知道那很难，哪里用得着灭亡郑国来增加邻邦（晋）的土地？","note":"鄙：意动；陪：增加。亡郑只利晋。","src":"烛之武退秦师"},{"q":"高祖忍之，养其全锋而待其弊，此子房教之也。","a":"高祖能忍，保全自己全部的锋芒而等待对方疲敝，这都是张良教给他的。","note":"弊：疲困。写张良以“忍”教高祖。","src":"留侯论"},{"q":"季氏将伐颛臾。冉有、季路见于孔子曰：“季氏将有事于颛臾。”","a":"季康子准备讨伐颛臾。冉有、子路去见孔子说：\"季氏将对颛臾采取军事行动。\"","note":"见：谒见；有事：指用兵。","src":"季氏将伐颛臾"},{"q":"远诚畏死，何苦守尺寸之地，食其所爱之肉，以与贼抗而不降乎？","a":"许远如果真的怕死，为什么要坚守这小小地盘，吃他所爱之人的肉，来和叛军对抗而不投降呢？","note":"诚：果真，表假设；何苦：何必。反诘句，有力反驳“畏死”之说。","src":"张中丞传后叙"},{"q":"夏四月戊午，晋侯使吕相绝秦，曰：“昔逮我献公及穆公相好，戮力同心，申之以盟誓，重之以昏姻。天祸晋国，文公如齐，惠公如秦。无禄，献公即世。穆公不忘旧德，俾我惠公用能奉祀于晋。又不能成大勋，而为韩之师。亦悔于厥心，用集我文公，是穆之成也。","a":"夏天四月戊午日，晋厉公派吕相去和秦国断绝邦交，说：\"从前我们献公和贵国穆公相互友好，合力同心，用盟誓加以申明，又用婚姻关系加以巩固。上天降祸给晋国，文公流亡齐国，惠公流亡秦国。不幸，献公去世。穆公没有忘记过去的恩德，使我惠公能够回国主持祭祀。后来惠公没能成就大功，于是发生了韩原之战。穆公心中也有悔意，就帮助我文公回国，这是穆公的成就。","note":"绝：断绝邦交；戮力同心：合力同心；申：申明；重：加重、巩固；即世：去世；俾：使；集：使……回国安定。","src":"吕相绝秦"},{"q":"朝菌不知晦朔，蟪蛄不知春秋，此小年也。","a":"朝菌不知道一个月的首尾，蟪蛄不知道一年的四季，这就是短寿。","note":"判断句。晦朔：农历每月最后一天和初一；蟪蛄：寒蝉。比喻小年。","src":"逍遥游"},{"q":"如必自为而后用之，是率天下而路也。","a":"如果一定要自己制作出来才使用，这是率领天下的人疲于奔命。","note":"路：疲惫、疲于道路。比喻强迫人人皆自为其用的恶果。","src":"许行"}]}]};
